/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A34 staging source: frozen 80-lemma manifest; publish only after final audit. */
'use strict';
const D = globalThis.RA.D;
const E = (origin, word) => ({origin, prefix:null, root:null, suffix:null, history:[], formationLogic:'', mnemonic:null, note:'Historical details are limited to the stated, supported formation.', source:'Etymonline — https://www.etymonline.com/word/'+word.toLowerCase()});
const C = (senseId, domain, en, zh, structure, grammar, rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M = (wrong,right,reason,errorType='meaning') => ({wrong,right,reason,errorType});
const Q = (w,n,s,prompt,a,b,c,answer,explain,errorType='meaning') => ({id:w+'.q'+n,senseId:w+'.s'+s,errorType,type:'辨义与用法',prompt,options:[a,b,c],answer,explain});


D('fictional',{etymology:E('Fictional is formed from fiction, ultimately from Latin fictio “a shaping or invention,” plus the adjective suffix -al. It describes something invented for a story or existing only in a work of fiction.','fictional'),contexts:[C('fictional.s2','小说人物','The novelist gave the fictional detective a hometown, a family history, and a habit of checking every train timetable before an interview.','小说家为这位虚构侦探设定了家乡、家庭经历，还让他在采访前习惯核对每一张列车时刻表。','The novelist gave the fictional detective a hometown / a family history / and a habit of checking every train timetable before an interview.','fictional 修饰 detective，表示人物只存在于小说创作中。','侦探由小说家创作，符合“小说中的”义 s2。')],mistakes:[M('The archive confirmed that the fictional detective had a real passport and had interviewed actual suspects.','The archive confirmed that the detective was real, not fictional, and had interviewed actual suspects.','真实护照与真实采访证明此人并非只存在于小说中。')],quiz:[Q('fictional',1,1,'A fictional village in a novel is?','invented for the story','a verified town on a current map','a village used only for farming','invented for the story','s1 指为故事创作、并非真实存在的事物。'),Q('fictional',2,2,'A fictional detective is one who?','appears as a character in an invented work','has a real police badge by definition','writes the novel rather than appearing in it','appears as a character in an invented work','s2 指小说、戏剧或电影中的人物。'),Q('fictional',3,1,'Which detail makes a place fictional?','Its author invented it for a plot.','A government survey marks its real coordinates.','Residents file taxes there.','Its author invented it for a plot.','由作者为情节创造说明其虚构。'),Q('fictional',4,2,'In “fictional character,” fictional means?','belonging to an invented story','based on a certified legal record','physically made of paper','belonging to an invented story','fictional character 是作品中的虚构角色。')]});
D('fictitious',{etymology:E('Fictitious came through French from Latin ficticius “artificial, counterfeit,” related to fingere “shape, invent.” It often suggests a deliberately invented, untrue name or account.','fictitious'),contexts:[C('fictitious.s1','登记信息','The applicant used a fictitious address on the form, so the clerk returned it and asked for a location where the applicant could actually be reached.','申请人在表格上填写了虚构地址，因此办事员退回表格，并要求提供一个确实能够联系到申请人的地址。','The applicant used a fictitious address on the form / so the clerk returned it / and asked for a location / where the applicant could actually be reached.','fictitious 修饰 address，强调其并非真实地址；where 从句限定可联系到的地点。','无法据此联系申请人，说明地址是编造而非真实地址，符合 s1。')],mistakes:[M('The bank verified the fictitious account by visiting the customer at the real address printed on it.','The bank rejected the fictitious account because the address printed on it was invented.','“核实为真实地址”与 fictitious（编造的）相冲突。')],quiz:[Q('fictitious',1,1,'A fictitious name on a form is?','made up rather than genuine','the applicant’s legal name','a name copied from a birth certificate','made up rather than genuine','s1 常指为误导而编造的姓名或资料。'),Q('fictitious',2,2,'A fictitious planet in a fantasy novel?','exists only in the imagined world','has been confirmed by astronomers','is necessarily a false invoice','exists only in the imagined world','s2 指只存在于想象中的事物。'),Q('fictitious',3,1,'Which is the clearest fictitious detail in an application?','A false street address invented to conceal the applicant.','A current address checked against an official record.','A telephone number answered by the applicant.','A false street address invented to conceal the applicant.','捏造地址用于隐瞒身份，符合编造、不真实的义项。'),Q('fictitious',4,1,'“Fictitious expenses” in an audit would be?','expenses that were invented and never incurred','receipts paid and recorded accurately','future costs clearly marked as estimates','expenses that were invented and never incurred','审计语境中 fictitious 指伪造、未实际发生的费用。')]});
D('fictive',{etymology:E('Fictive comes from Latin fictivus, from fingere “to shape or invent.” It is a relatively formal adjective meaning created by imagination rather than factual.','fictive'),contexts:[C('fictive.s1','回忆录写作','The editor marked the fictive dialogue in the memoir because no transcript existed, while leaving the documented dates and letters unchanged.','编辑标出了回忆录中虚构的对话，因为并无录音记录，同时保留了有文件佐证的日期和信件。','The editor marked the fictive dialogue in the memoir / because no transcript existed / while leaving the documented dates and letters unchanged.','fictive 作定语修饰 dialogue；while 对比虚构对话与有据可查的材料。','对话由作者想象补写、没有录音，而周边材料有记录，符合“非事实的创作”义。')],mistakes:[M('The historian called the signed court transcript fictive because it had been independently authenticated.','The historian called the imagined dialogue fictive, while treating the authenticated court transcript as factual.','经独立认证的法庭记录有事实依据，不应称为想象创作。')],quiz:[Q('fictive',1,1,'A fictive scene in a memoir is?','imagined rather than supported as an actual event','a scene copied from a verified recording','a scene that must be filmed outdoors','imagined rather than supported as an actual event','fictive 表示想象创作而非事实。'),Q('fictive',2,1,'Why might an editor label a passage fictive?','It was invented to fill a gap in the narrative.','A document independently confirms every line.','The passage contains only dates.','It was invented to fill a gap in the narrative.','虚构补写的段落并非有材料证明的真实记录。'),Q('fictive',3,1,'Choose the closest contrast for fictive in historical writing.','documented','imagined','invented','documented','fictive 与有记录佐证的 documented 相对。'),Q('fictive',4,1,'A fictive character is best described as?','created by an author’s imagination','a person whose identity is verified in a census','a machine part with a serial number','created by an author’s imagination','fictional character 由创作者想象出来。')]});
D('fiddler',{etymology:E('Fiddler is formed from fiddle, a familiar name for a violin, plus the agent suffix -er. The instrument name is recorded in English by the Middle Ages and its deeper origin is uncertain.','fiddler'),contexts:[C('fiddler.s1','民间音乐','A fiddler played quick reels while the dancers stamped the wooden floor, then changed to a slower tune for the older guests.','一位小提琴手演奏着轻快的里尔舞曲，舞者跺着木地板起舞，随后他又为年长宾客换了一支较慢的曲子。','A fiddler played quick reels / while the dancers stamped the wooden floor / then changed to a slower tune / for the older guests.','fiddler 是以 fiddle（小提琴）演奏者命名的施事名词。','演奏里尔舞曲并更换乐曲的人是拉小提琴的人。')],mistakes:[M('The fiddler tuned a violin and then played the melody on a trumpet.','The fiddler tuned a violin and then played the melody on it.','把小提琴调好后却用小号演奏，与 fiddler 的身份不一致。')],quiz:[Q('fiddler',1,1,'At a folk dance, a fiddler usually?','plays a violin','repairs a fishing net','leads a courtroom hearing','plays a violin','fiddler 指演奏 fiddle（小提琴）的人。'),Q('fiddler',2,1,'Which instrument would a fiddler tune before a reel?','a violin','a drum kit only','a pipe organ only','a violin','reel 常由小提琴演奏，fiddler 即提琴手。'),Q('fiddler',3,1,'In the word fiddler, -er most directly marks?','a person who performs an action','the past tense of fiddle','a place where instruments are stored','a person who performs an action','-er 构成施事者名称。'),Q('fiddler',4,1,'A fiddler in a village band is most likely to be?','the player of the violin part','the person who sells all the tickets','the composer of every song by necessity','the player of the violin part','fiddler 的核心义是拉小提琴的人。')]});
D('fidelity',{etymology:E('Fidelity came through French from Latin fidelitas, from fidelis “faithful,” ultimately related to fides “faith.” English uses it for loyalty and for accurate reproduction of a signal or image.','fidelity'),contexts:[C('fidelity.s3','音响测试','The laboratory compared the recording with the live performance and measured how much fidelity the speakers preserved across the full frequency range.','实验室将录音与现场演出进行比较，并测量扬声器在整个频率范围内保留了多少保真度。','The laboratory compared the recording with the live performance / and measured how much fidelity the speakers preserved / across the full frequency range.','fidelity 作不可数名词表示复制或再现的精确程度。','对比录音与现场声并测量保留程度，体现技术义 s3。')],mistakes:[M('The archivist praised the scan’s fidelity because it omitted half the original pages and changed every date.','The archivist criticized the scan’s low fidelity because it omitted half the original pages and changed every date.','遗漏页面、篡改日期说明复制失真，不能称高保真。')],quiz:[Q('fidelity',1,1,'Fidelity to a promise means?','remaining loyal to it','changing it whenever convenient','forgetting that it was made','remaining loyal to it','s1 表示对承诺忠实、守信。'),Q('fidelity',2,2,'Marital fidelity concerns?','faithfulness between spouses','the sound quality of a radio','a legal name on a form','faithfulness between spouses','s2 特指婚姻中的忠贞。'),Q('fidelity',3,3,'High-fidelity speakers aim to?','reproduce sound accurately','make every recording quieter','remove all high frequencies','reproduce sound accurately','s3 表示声音复制的精确程度。'),Q('fidelity',4,3,'A faithful image copy has high fidelity when it?','preserves the original details closely','adds invented people to the scene','drops the original colors and shapes','preserves the original details closely','图像保真度高意味着准确保留原图细节。')]});
D('fieldstone',{etymology:E('Fieldstone combines field and stone. The compound names rough stones found naturally in fields and, by extension, uncut stone used in rustic building.','fieldstone'),contexts:[C('fieldstone.s2','乡村建筑','The cottage’s fieldstone walls were built from rough local rock, with the largest blocks placed at the corners for stability.','农舍的粗石墙由当地未经细琢的岩石砌成，最大的石块被放在墙角以保持稳固。','The cottage’s fieldstone walls were built from rough local rock / with the largest blocks placed at the corners / for stability.','fieldstone 在此作定语，说明墙由粗石砌成。','句中强调建筑材料未经细琢，符合 s2。')],mistakes:[M('The builder described the polished marble blocks as fieldstone although they had been cut and shaped in a factory.','The builder described the rough, naturally gathered stones as fieldstone before using them in the wall.','光滑、工厂切制的装饰石不符合 fieldstone 的天然粗石含义。')],quiz:[Q('fieldstone',1,1,'A fieldstone found while ploughing is?','a rough stone lying naturally in a field','a polished glass tile','a metal fence post','a rough stone lying naturally in a field','s1 指田间自然散落的粗石。'),Q('fieldstone',2,2,'A fieldstone wall is generally made from?','rough, uncut stones','thin sheets of plastic','uniform polished marble slabs','rough, uncut stones','s2 指作为建筑材料的未经细琢粗石。'),Q('fieldstone',3,1,'Why might farmers pile fieldstones at a field edge?','to clear naturally scattered rocks from the soil','to store harvested grain','to mark a river’s depth','to clear naturally scattered rocks from the soil','田里自然散石妨碍耕作，可移到田边堆放。'),Q('fieldstone',4,2,'Which material best fits a fieldstone cottage wall?','locally gathered rough stone blocks','factory-polished glass panels','a woven cotton sheet','locally gathered rough stone blocks','粗石墙用的是天然、未经精加工的石块。')]});
D('fieldwork',{etymology:E('Fieldwork combines field in the sense of an area of study or activity and work. It names research or practical training done at the site rather than solely in a classroom or laboratory.','fieldwork'),contexts:[C('fieldwork.s1','方言调查','The linguists spent three weeks doing fieldwork in the valley, recording how older residents pronounced the names of local plants.','语言学家在山谷里进行了三周实地调查，记录年长居民如何读出当地植物的名称。','The linguists spent three weeks doing fieldwork in the valley / recording how older residents pronounced the names of local plants.','do fieldwork 表示开展实地研究；现在分词短语说明调查内容。','研究者到语言使用现场记录发音，符合实地研究义。')],mistakes:[M('The team called its fieldwork a desk study because every interview came from a textbook and no researcher visited the valley.','The team called its project desk research because every interview came from a textbook and no researcher visited the valley.','未去现场、仅查阅书籍不属于 fieldwork。')],quiz:[Q('fieldwork',1,1,'An ecologist doing fieldwork is likely to?','collect observations at the study site','work only from a copied office chart','edit a novel about wildlife','collect observations at the study site','fieldwork 是到现场开展的研究或训练。'),Q('fieldwork',2,1,'Which activity is clearest fieldwork?','interviewing residents in the village being studied','reading a summary without visiting the village','filing invoices at headquarters','interviewing residents in the village being studied','在研究地点访谈当地人属于实地调查。'),Q('fieldwork',3,1,'Fieldwork contrasts most directly with research done?','only indoors or at a desk','in the location being studied','with observations made on site','only indoors or at a desk','其核心区分是现场与纯室内/书桌研究。'),Q('fieldwork',4,1,'A geography course requires fieldwork so students can?','observe landforms and collect data outdoors','memorize a glossary without leaving the library','replace maps with fictional stories','observe landforms and collect data outdoors','实地课程要求学生到野外观察并收集资料。')]});
D('fiercely',{etymology:E('Fiercely is the adverb formed from fierce and -ly. Fierce came through French from Latin ferus “wild”; the adverb can describe force, anger, or determined opposition.','fiercely'),contexts:[C('fiercely.s1','社区反对','Residents fiercely opposed the quarry proposal because the traffic study ignored the narrow road beside the primary school.','居民强烈反对采石场方案，因为交通评估忽视了小学旁边那条狭窄道路。','Residents fiercely opposed the quarry proposal / because the traffic study ignored the narrow road / beside the primary school.','fiercely 修饰 opposed，说明反对的态度强烈。','强烈反对并提出安全理由，体现副词的激烈程度义。')],mistakes:[M('The union fiercely supported the plan by refusing to endorse it, rejecting it, and urging members to oppose it.','The union fiercely opposed the plan by refusing to endorse it, rejecting it, and urging members to oppose it.','后续行为都是反对，与 supported 相矛盾。')],quiz:[Q('fiercely',1,1,'A fiercely contested election is?','argued over or fought for with great intensity','settled quietly with no disagreement','cancelled before anyone votes','argued over or fought for with great intensity','fiercely 表示程度强烈、激烈。'),Q('fiercely',2,1,'If two siblings fiercely defend their views, they?','argue with strong determination','forget what each view was','agree without discussion','argue with strong determination','副词可描述坚定而激烈地维护立场。'),Q('fiercely',3,1,'Which collocation is natural?','fiercely opposed the proposal','fiercely asleep the proposal','fiercely into the proposal','fiercely opposed the proposal','fiercely 可修饰表示强烈反对的 oppose。'),Q('fiercely',4,1,'“Fiercely loyal” most nearly means?','loyal with very strong commitment','loyal only by accident','not loyal to anyone','loyal with very strong commitment','fiercely 强化 loyal，表示十分忠诚。')]});
D('figment',{etymology:E('Figment comes from Latin figmentum “a thing fashioned or invented,” from fingere “to shape.” It commonly appears in “a figment of the imagination” and can also mean a baseless invented account.','figment'),contexts:[C('figment.s1','误认影子','The “figure” in the dark doorway was only a figment of Mei’s imagination; the security camera showed that no one had entered the room.','黑暗门口的“人影”只是梅的凭空想象；监控显示根本没有人进过房间。','The “figure” in the dark doorway was only a figment of Mei’s imagination / the security camera showed / that no one had entered the room.','a figment of someone’s imagination 是常用搭配。','监控证实门口没有人，说明人影只存在于想象中，符合 s1。')],mistakes:[M('The witness called the documented payment a figment of the imagination even though the bank statement independently confirmed it.','The witness called the imagined payment a figment of the imagination because no record supported it.','银行记录证实的付款不是凭空想象。')],quiz:[Q('figment',1,1,'A noise that proves to be a figment of someone’s imagination?','was imagined rather than actually heard','was recorded clearly by several devices','came from a verified machine','was imagined rather than actually heard','s1 表示头脑中想象出来、现实中没有的事物。'),Q('figment',2,2,'A “figment” used for an excuse with no evidence is?','an invented account','a certified fact','a physical instrument','an invented account','s2 指没有事实依据的编造说法。'),Q('figment',3,1,'Which phrase is especially common?','a figment of the imagination','a figment under the keyboard','a figment for three kilograms','a figment of the imagination','该词常出现在 a figment of the imagination 中。'),Q('figment',4,2,'Why reject a claim as a figment?','It has been made up without factual support.','It has been confirmed by several records.','It is too heavy to carry.','It has been made up without factual support.','无事实依据的臆造符合 s2。')]});
D('figural',{etymology:E('Figural derives from Latin figura “shape, form” through figure and the adjective ending -al. In art it distinguishes recognizable human or animal forms from nonrepresentational pattern.','figural'),contexts:[C('figural.s1','艺术展览','The gallery grouped the figural canvases together: each showed recognizable people or animals rather than lines arranged as a pure geometric pattern.','美术馆把具象画作放在一起：每幅都画出了可辨认的人或动物，而不是纯几何图案的线条。','The gallery grouped the figural canvases together / each showed recognizable people or animals / rather than lines arranged as a pure geometric pattern.','figural 修饰 canvases，说明作品呈现可辨认的形体。','人和动物形象与纯抽象图案相对，正是 figural 的艺术义。')],mistakes:[M('The curator called a canvas figural even though it contained only repeated squares and no recognizable bodies.','The curator called a canvas abstract because it contained only repeated squares and no recognizable bodies.','没有任何可辨认的人或动物形体的画作，不符合此处 figural 的定义。')],quiz:[Q('figural',1,1,'A figural sculpture clearly depicts?','a recognizable human or animal form','only an arrangement of unrecognizable dots','a written argument with no image','a recognizable human or animal form','figural 在艺术中指表现可辨认形体。'),Q('figural',2,1,'What most clearly contrasts with figural art?','pure nonrepresentational pattern','a portrait of a person','a statue shaped like a horse','pure nonrepresentational pattern','figural 强调形象可辨认，纯图案则不表现具体形体。'),Q('figural',3,1,'A museum labels a carving “figural.” It is likely to show?','a body or animal shape','a blank square of stone','a list of dates only','a body or animal shape','标签表示雕刻呈现人或动物形体。'),Q('figural',4,1,'Which exhibit is figural?','a bronze human figure with visible limbs','a repeating pattern of parallel lines only','an empty frame','a bronze human figure with visible limbs','有明确人体形象的雕塑属于具象作品。')]});
D('figurative',{etymology:E('Figurative comes from Latin figurativus, based on figura “figure, form,” through French and figure. It describes language used symbolically or metaphorically rather than in its literal physical sense.','figurative'),contexts:[C('figurative.s1','比喻表达','When the editor said the proposal had “legs,” she meant it could survive scrutiny and move forward, not that the pages had grown limbs; the expression was figurative.','编辑说这个提案“有腿”时，意思是它经得住审查并能继续推进，而不是纸页长出了肢体；这是比喻说法。','When the editor said the proposal had “legs” / she meant it could survive scrutiny and move forward / not that the pages had grown limbs / the expression was figurative.','figurative 修饰 expression，表示不按字面物理意义理解。','proposal 没有真实肢体，legs 表示可持续发展，体现比喻义。')],mistakes:[M('In its figurative sense, “the proposal has legs” means the paper literally grew two limbs.','In its figurative sense, “the proposal has legs” means it is likely to continue or succeed.','把 figurative 表达解释成真实长出肢体，混淆了比喻与字面。')],quiz:[Q('figurative',1,1,'A figurative use of “burning question” means the question is?','urgent or emotionally important','literally on fire','written with a red pencil only','urgent or emotionally important','figurative language uses symbolic rather than physical meaning.','meaning'),Q('figurative',2,1,'A “storm of protest” is figurative because?','the protest is not actual weather','rain is falling on the speakers','the protest occurs on a ship','the protest is not actual weather','storm 比喻大量而强烈的抗议。'),Q('figurative',3,1,'Which is a figurative statement?','The news opened a door to further talks.','She opened the wooden door with a key.','The door was two metres tall.','The news opened a door to further talks.','新闻不能真的打开门，此处 door 比喻机会。'),Q('figurative',4,1,'A figurative expression should be interpreted?','symbolically rather than as a strict physical description','only by measuring its physical objects','as necessarily false grammar','symbolically rather than as a strict physical description','figurative 与严格字面描述相对。')]});
D('figuratively',{etymology:E('Figuratively is the adverb from figurative plus -ly. The adjective ultimately comes from Latin figura “form, figure”; the adverb signals a symbolic rather than strictly physical reading.','figuratively'),contexts:[C('figuratively.s1','团队压力','Figuratively speaking, the deadline was a wall in front of the team: they needed to change the schedule, not search for a brick barrier in the office.','打个比方说，截止日期像挡在团队面前的一堵墙：他们需要调整安排，而不是去办公室里找一堵砖墙。','Figuratively speaking / the deadline was a wall in front of the team / they needed to change the schedule / not search for a brick barrier in the office.','figuratively speaking 常用来提示接下来的话是比喻。','截止日期不是实体墙，该副词提示象征意义。')],mistakes:[M('She said figuratively that the meeting room was literally filled with an ocean of paperwork, then insisted no papers were present.','She said figuratively that the meeting room was buried under paperwork, though no literal ocean was present.','figuratively 表示比喻；“literally”且坚称没有纸张相互矛盾。')],quiz:[Q('figuratively',1,1,'“Figuratively speaking, I hit a wall” means?','I met an obstacle','I struck a brick surface with my hand','I built a wall','I met an obstacle','figuratively 表示 hit a wall 按比喻理解为遇到阻碍。'),Q('figuratively',2,1,'Why add “figuratively” before “drowned in work”?','to show no actual water is involved','to report a real accident in a pool','to describe a swimming lesson','to show no actual water is involved','该副词提示 drowned 是比喻说法。'),Q('figuratively',3,1,'Choose a sentence using figuratively.','Figuratively, the rumor followed him everywhere.','The boat was figuratively full of water after the leak.','Figuratively, the bridge is made of steel.','Figuratively, the rumor followed him everywhere.','传言不会真的跟随某人，句中用作比喻。'),Q('figuratively',4,1,'If a speaker says “figuratively,” listeners should expect?','a nonliteral comparison or image','a precise measurement of an object','a guarantee that every word is a lie','a nonliteral comparison or image','它提示听者按象征或比喻意义理解。')]});
D('figurehead',{etymology:E('Figurehead combines figure and head. It first named the carved figure fixed at a ship’s bow, then developed a figurative sense for a nominal leader with little real authority.','figurehead'),contexts:[C('figurehead.s2','机构治理','The foundation’s director was a figurehead: she appeared at ceremonies, but the board controlled the budget and made every substantive decision.','这家基金会的主任只是名义上的首领：她出席典礼，但预算由董事会掌控，所有实质决定也由董事会作出。','The foundation’s director was a figurehead / she appeared at ceremonies / but the board controlled the budget / and made every substantive decision.','冒号后的内容解释 figurehead 的实际无权状态。','决策权在董事会，主任只有礼仪性露面，符合傀儡首领义 s2。')],mistakes:[M('Although the elected chair personally set policy and controlled every vote, the report called her a powerless figurehead.','Because the board set policy and controlled every vote, the report called the ceremonial chair a figurehead.','拥有实质决策权的人不符合“只有头衔、没有实权”的比喻义。')],quiz:[Q('figurehead',1,1,'A ship’s figurehead was traditionally?','a carved figure fixed to the bow','the captain’s private cabin','a flag raised from the mast','a carved figure fixed to the bow','s1 是固定在旧船船头的雕像。'),Q('figurehead',2,2,'A political figurehead has a title but?','little or no real power','complete control of every decision','no public role at all','little or no real power','s2 指名义上的领导，实权由别人掌握。'),Q('figurehead',3,2,'Which person is most clearly a figurehead?','a ceremonial president whose council makes all decisions','a prime minister who sets policy and directs the cabinet','a judge who issues binding rulings','a ceremonial president whose council makes all decisions','实权由委员会掌握者只是名义领袖。'),Q('figurehead',4,1,'Where would the original, literal figurehead be found?','at the front of an old sailing ship','inside a modern ballot box','under a railway platform','at the front of an old sailing ship','字面义指船头装饰雕像。')]});
D('figurine',{etymology:E('Figurine came through French figurine, a diminutive of figure, from Latin figura “shape, form.” It names a small modelled figure used as an ornament or in a ritual.','figurine'),contexts:[C('figurine.s1','考古发现','The archaeologist photographed the clay figurine beside the hearth before lifting it, noting its small human shape and the layer of ash around it.','考古学家在拿起炉边的陶制小雕像前先拍照，并记录了它小巧的人形以及周围的灰烬层。','The archaeologist photographed the clay figurine beside the hearth / before lifting it / noting its small human shape and the layer of ash around it.','figurine 指小型塑像；clay 修饰材质。','小巧的陶制人像符合装饰或礼仪用小雕像义。')],mistakes:[M('The museum catalogued a life-size marble statue as a tiny figurine even though it stood taller than the visitors.','The museum catalogued the small clay model as a figurine and the life-size marble work as a statue.','超过真人大小的雕像不符合 figurine 的“小型塑像”特征。')],quiz:[Q('figurine',1,1,'A ceramic figurine is usually?','a small modelled figure','a full-size stone bridge','a printed legal form','a small modelled figure','figurine 指小型塑像。'),Q('figurine',2,1,'Which object best fits the word figurine?','a tiny carved fox displayed on a shelf','a life-size bronze horse in a square','a flat map of the city','a tiny carved fox displayed on a shelf','架上展示的小型动物雕像符合定义。'),Q('figurine',3,1,'A figurine may serve as?','an ornament or ritual object','a large vehicle engine','a weather report','an ornament or ritual object','小雕像可作装饰品或礼仪物件。'),Q('figurine',4,1,'Why is a statuette called a figurine?','it is a small formed figure','it contains no shape','it is always made of paper','it is a small formed figure','figurine 的构词和释义都指小型形象。')]});
D('filament',{etymology:E('Filament comes from French filament, formed from Latin filum “thread” and the noun ending -ment. It names a very slender thread or wire, especially the wire that glows inside an incandescent bulb.','filament'),contexts:[C('filament.s1','灯泡维修','The old bulb went dark when its filament snapped, although the glass envelope and the socket were still intact.','旧灯泡的灯丝断裂后就不亮了，尽管玻璃外壳和灯座仍然完好。','The old bulb went dark / when its filament snapped / although the glass envelope and the socket were still intact.','filament 在此指灯泡内部发光的细金属丝。','灯泡玻璃和灯座完好但内部细丝断裂，解释了失效原因。')],mistakes:[M('The repairer blamed the broken filament for the bulb’s failure, although the filament was a thick wooden pole outside the glass.','The repairer blamed the broken filament inside the bulb for its failure.','灯泡里的 filament 是细丝，不是玻璃外的木杆。')],quiz:[Q('filament',1,1,'The filament in an old light bulb is?','a thin wire that glows when heated','the glass shade around the bulb','the switch on the wall','a thin wire that glows when heated','灯泡灯丝是通电后发光的细金属丝。'),Q('filament',2,1,'A plant filament is generally?','a slender threadlike part','a broad stone wall','a noisy electrical motor','a slender threadlike part','该词也可泛指细丝状结构。'),Q('filament',3,1,'What likely happens if a bulb filament breaks?','the bulb stops producing light','the socket becomes a tree branch','the glass automatically doubles in size','the bulb stops producing light','灯丝断裂会中断发光。'),Q('filament',4,1,'Which object could reasonably be called a filament?','a very fine conducting wire','a thick concrete pillar','a wide sheet of plywood','a very fine conducting wire','filament 的形状特征是细长如丝。')]});
D('filch',{etymology:E('Filch is recorded in English in the sixteenth century for stealing small items; its deeper origin is uncertain. The verb usually suggests taking something secretly and without great value.','filch'),contexts:[C('filch.s1','办公室零食','Someone filched the last biscuit from the tin while the meeting was underway, leaving the empty wrapper under the minutes.','会议进行时，有人偷偷拿走了罐里最后一块饼干，还把空包装留在会议纪要下面。','Someone filched the last biscuit from the tin / while the meeting was underway / leaving the empty wrapper under the minutes.','filch 是及物动词，后接被偷偷拿走的东西。','偷偷拿走一块小零食是非正式语境中的小额偷窃，符合 s1。')],mistakes:[M('The cashier openly filched a signed painting worth millions by announcing the theft on the museum loudspeaker.','The cashier secretly filched a small packet of biscuits from the staff kitchen.','公开拿取昂贵艺术品与 filch 暗中偷拿小东西的语气不符。')],quiz:[Q('filch',1,1,'If a visitor filches a pencil, the visitor?','takes it secretly without permission','borrows it openly and returns it','sharpens it for the owner','takes it secretly without permission','filch 表示偷偷拿走，常指价值不高的东西。'),Q('filch',2,1,'Which action best fits filch?','quietly slipping a few biscuits into one’s bag','buying a box of biscuits at the shop','asking to borrow a pen and receiving permission','quietly slipping a few biscuits into one’s bag','暗中拿走小物品最符合 filch。'),Q('filch',3,1,'In “filch a wallet,” the wallet is?','the object secretly taken','the person who commits the act','the place where money is printed','the object secretly taken','filch 作及物动词，wallet 是其宾语。'),Q('filch',4,1,'Filch is closest in meaning to?','steal furtively','donate generously','display proudly','steal furtively','其核心是偷偷偷拿。')]});
D('filial',{etymology:E('Filial came from Latin filialis, based on filius “son” and filia “daughter.” It describes a child’s relationship or duty toward a parent, including respect and care.','filial'),contexts:[C('filial.s1','家庭照护','Her filial responsibility did not mean obeying every demand; it meant arranging safe care for her father and listening respectfully to his wishes.','她作为子女的责任并不意味着服从每项要求，而是为父亲安排安全照护并尊重地听取他的意愿。','Her filial responsibility did not mean obeying every demand / it meant arranging safe care for her father / and listening respectfully to his wishes.','filial 修饰 responsibility，表示子女对父母的责任。','为父亲照护并尊重其意愿体现子女关系中的责任。')],mistakes:[M('The son described a stranger’s duty to his employer as a filial duty toward his parents.','The son described his duty to care for his parents as a filial responsibility.','filial 针对子女与父母的关系，不是对雇主的一般责任。')],quiz:[Q('filial',1,1,'Filial respect is respect shown by?','a child toward a parent','a customer toward a shop sign','a pilot toward an aircraft engine','a child toward a parent','filial 与子女对父母的关系有关。'),Q('filial',2,1,'Which is an example of filial care?','an adult child arranging support for an aging parent','a manager assigning shifts to employees','a mechanic servicing a stranger’s car for pay','an adult child arranging support for an aging parent','成年子女照护父母是子女责任的例子。'),Q('filial',3,1,'The phrase “filial duty” most likely concerns?','responsibilities within a parent-child relationship','a duty owed by a ship to its harbor','an employee’s tax bill','responsibilities within a parent-child relationship','filial duty 指子女对父母的责任。'),Q('filial',4,1,'Choose the natural collocation.','filial devotion','filial rainfall','filial engine oil','filial devotion','filial devotion 表示子女对父母的关爱。')]});
D('filler',{etymology:E('Filler is formed from fill plus the agent or instrument suffix -er. It names material that fills a space and, figuratively, content used to occupy time or space without adding much value.','filler'),contexts:[C('filler.s1','杂志编辑','The editor cut three pages of filler from the issue because the short interviews repeated facts already covered in the main report.','编辑从这期刊物中删掉了三页凑数内容，因为那些简短采访重复了主报道已有的事实。','The editor cut three pages of filler from the issue / because the short interviews repeated facts / already covered in the main report.','filler 在此指为填版面而加入、信息价值有限的内容。','被删除的采访仅重复信息，是内容上的补白，符合 s1。')],mistakes:[M('The magazine called the original, carefully researched investigation filler because it added the issue’s most important new evidence.','The magazine called the repetitive material filler because it added little information beyond the main report.','提供最重要新证据的调查并非无实质内容的凑数材料。')],quiz:[Q('filler',1,1,'In a magazine, filler is often?','content added mainly to occupy space','the central investigation with all new evidence','the publication date on the cover','content added mainly to occupy space','filler 可指信息价值不大的补白。'),Q('filler',2,1,'A carpenter applies wood filler to?','fill cracks or gaps','polish a window into glass','measure a roof’s height','fill cracks or gaps','实物义的 filler 用来填补缝隙。'),Q('filler',3,1,'Why might a meeting include filler discussion?','to occupy time without advancing the decision','to settle the key question immediately','to publish the final report','to occupy time without advancing the decision','比喻义表示占用时间但无多大价值的内容。'),Q('filler',4,1,'Which sentence uses filler figuratively?','The episode had ten minutes of filler before the plot resumed.','The mason pressed filler into the wall crack.','The mechanic filled the tank with fuel.','The episode had ten minutes of filler before the plot resumed.','剧情恢复前的冗长段落是内容上的凑数部分。')]});
D('filmmaker',{etymology:E('Filmmaker combines film and maker. Film entered English for a thin layer and later for photographic material; the compound names a person who creates films, often as a director or producer.','filmmaker'),contexts:[C('filmmaker.s1','纪录片制作','The filmmaker spent three winters following the fishing families, then edited their interviews into a documentary about changes along the coast.','这位电影制作人花了三个冬天跟访渔民家庭，随后把访谈剪辑成一部讲述海岸变化的纪录片。','The filmmaker spent three winters following the fishing families / then edited their interviews / into a documentary about changes along the coast.','filmmaker 指参与创作电影的人；此处兼有拍摄与剪辑工作。','跟访、采访并剪辑成片体现电影创作者义。')],mistakes:[M('The filmmaker wrote a cinema review but had no role in creating, directing, or producing any film.','The filmmaker directed the documentary and shaped how its interviews and images appeared on screen.','只评论电影而未参与制作的人是影评人，不是 filmmaker。')],quiz:[Q('filmmaker',1,1,'A filmmaker is someone who?','creates films, often by directing or producing','only sells tickets at a cinema','repairs the cinema seats','creates films, often by directing or producing','filmmaker 指参与电影创作的人。'),Q('filmmaker',2,1,'Which task is most likely part of a filmmaker’s work?','planning and shaping a documentary','checking a train’s brakes','translating a restaurant menu only','planning and shaping a documentary','导演或制片等创作工作属于电影制作。'),Q('filmmaker',3,1,'The compound filmmaker is made from?','film + maker','fill + farmer','fidelity + marker','film + maker','该词由 film 与 maker 构成。'),Q('filmmaker',4,1,'A person who directs a short film can be called a?','filmmaker','filament','fieldstone','filmmaker','导演短片的人参与制作电影，属于 filmmaker。')]});
D('filmy',{etymology:E('Filmy is formed from film plus -y, with the older “thin layer” sense of film. It describes something very thin and light, often translucent like a membrane.','filmy'),contexts:[C('filmy.s1','窗帘材质','A filmy curtain softened the afternoon light without darkening the room, and the open window made the fabric drift gently.','一层薄如轻纱的窗帘柔化了午后的光线，却没有让房间变暗；敞开的窗户使布料轻轻飘动。','A filmy curtain softened the afternoon light / without darkening the room / and the open window made the fabric drift gently.','filmy 修饰 curtain，强调薄、轻而半透明。','光能透过窗帘且布料轻飘，符合薄膜般的性质。')],mistakes:[M('The tailor described the filmy curtain as a thick opaque canvas that blocked every trace of daylight.','The tailor described the filmy curtain as a thin translucent fabric that softened the daylight.','厚重不透光的帆布与 filmy 的轻薄半透明含义相反。')],quiz:[Q('filmy',1,1,'A filmy veil is likely?','thin, light, and partly transparent','thick like a wooden door','made of solid metal','thin, light, and partly transparent','filmy 描述薄而轻、常半透明的质地。'),Q('filmy',2,1,'Why can a filmy curtain soften sunlight but still let light through?','its fabric is very thin and translucent','it is made from a brick wall','it contains no material at all','its fabric is very thin and translucent','薄纱可以透光而柔化光线。'),Q('filmy',3,1,'Which material is most plausibly filmy?','a sheer layer of gauze','a dense steel plate','a solid granite block','a sheer layer of gauze','轻薄纱布接近 filmy 的描述。'),Q('filmy',4,1,'Choose the closest description of filmy smoke.','a thin, light, hazy layer','a solid slab that cannot move','a clear liquid in a sealed jar','a thin, light, hazy layer','该形容词也能描述薄雾般的一层。')]});
D('filth',{etymology:E('Filth is an old English noun of Germanic history; its deeper formation is uncertain. It names extreme dirt and can also refer to obscene material.','filth'),contexts:[C('filth.s1','河道清理','Volunteers removed plastic, mud, and other filth from the stream after the storm.','暴风雨后，志愿者清除了溪流中的塑料、泥浆和其他污物。','Volunteers removed plastic, mud, and other filth / from the stream / after the storm.','filth 作不可数名词，指污秽物。','塑料和泥浆等污染物是脏污，符合义项。')],mistakes:[M('The kitchen was spotless, so the inspector said its counters were covered in filth.','The kitchen was spotless, so the inspector said its counters were free of filth.','spotless 与 covered in filth 相互矛盾。')],quiz:[Q('filth',1,1,'An alley ankle-deep in filth is?','extremely dirty','spotless and newly cleaned','filled with drinking water','extremely dirty','filth 指污秽、肮脏的东西。'),Q('filth',2,1,'Which could be called filth after a flood?','mud and waste in a room','clean sheets','fresh drinking water','mud and waste in a room','泥浆和废物是污秽。'),Q('filth',3,1,'“Cleared of filth” means?','dirt and waste were removed','all water disappeared','the road was widened','dirt and waste were removed','filth 是被清理掉的脏污。'),Q('filth',4,1,'Filth contrasts most directly with?','cleanliness','silence','height','cleanliness','filth 与洁净相对。')]});
D('filtration',{etymology:E('Filtration is built from filter and -ation. Filter entered English through French from medieval Latin filtrum, a piece of felt used to strain liquid.','filtration'),contexts:[C('filtration.s1','净水处理','Sand filtration traps suspended particles before the treatment plant disinfects the water.','砂滤先截留悬浮颗粒，之后水处理厂再对水消毒。','Sand filtration traps suspended particles / before the treatment plant disinfects the water.','filtration 是名词，sand filtration 指砂滤。','过滤材料截留水中固体，符合定义。')],mistakes:[M('The lab used filtration to dissolve sand into water without separating any particles.','The lab used filtration to separate sand particles from the water.','过滤是分离固液，不是把砂溶解。')],quiz:[Q('filtration',1,1,'Filtration aims to?','separate particles from a fluid','turn water into gas','add stones to water','separate particles from a fluid','过滤用滤材把固体从流体中分离。'),Q('filtration',2,1,'A filter catches sediment during?','filtration','combustion','fermentation','filtration','滤材截留沉积物是过滤过程。'),Q('filtration',3,1,'Which is filtration?','pouring coffee through paper','burning sugar','freezing a tool','pouring coffee through paper','滤纸截留咖啡渣，属于过滤。'),Q('filtration',4,1,'After filtration, unwanted particles are often?','held by the filter','changed into metal','made by the filter','held by the filter','过滤器截留杂质。')]});
D('fin',{etymology:E('Fin appears in Old English as finn for a fish’s swimming organ; its deeper Germanic history is uncertain. It can also name a similar stabilizing blade.','fin'),contexts:[C('fin.s1','鱼类观察','The trout adjusted its position in the current with its pectoral fins while its tail supplied forward thrust.','鳟鱼用胸鳍在水流中调整位置，尾部则提供向前的推力。','The trout adjusted its position in the current / with its pectoral fins / while its tail supplied forward thrust.','fin 指鱼运动或控制方向的鳍。','胸鳍调整方向，符合鱼鳍义。')],mistakes:[M('The trout steered with its fins, which were feathered wings on its shoulders.','The trout steered with its fins, the swimming organs along its body.','鱼鳍不是长在肩上的羽翼。')],quiz:[Q('fin',1,1,'A fish uses its fins to?','move and steer in water','grow feathers','breathe air through lungs','move and steer in water','鱼鳍帮助鱼游动和控制方向。'),Q('fin',2,1,'A rocket fin helps it?','remain stable','filter water','produce eggs','remain stable','设备上的 fin 可指稳定翼片。'),Q('fin',3,1,'Choose the natural phrase.','dorsal fin','dorsal feather','dorsal gillbone','dorsal fin','dorsal fin 是背鳍。'),Q('fin',4,1,'A surfboard fin helps the board?','track and stay stable','catch fire','become invisible','track and stay stable','冲浪板鳍片用于稳定和控制方向。')]});
D('financially',{etymology:E('Financially is formed from financial plus -ly; financial comes from finance and -al. It means “in terms of money.”','financially'),contexts:[C('financially.s1','机构预算','The museum is financially independent of the university, although they share conservation equipment.','这家博物馆在财务上独立于大学，尽管双方共用文物保护设备。','The museum is financially independent of the university / although they share conservation equipment.','financially 修饰 independent，说明独立的财务方面。','设备合作不影响各自资金独立，体现财务义。')],mistakes:[M('The project was financially viable because it had no funds and could not pay its staff.','The project was not financially viable because it had no funds and could not pay its staff.','没有资金且无法发薪，说明财务上不可行。')],quiz:[Q('financially',1,1,'A financially independent charity?','manages money without relying on another body','has no accounts by definition','works only overseas','manages money without relying on another body','financially 指财务方面。'),Q('financially',2,1,'A financially sound plan is?','reasonable in money terms','artistically beautiful','made of metal','reasonable in money terms','financially sound 指财务稳健。'),Q('financially',3,1,'Choose the correct phrase.','financially dependent on grants','financially dependently on grants','financial on dependent grants','financially dependent on grants','副词 financially 修饰形容词 dependent。'),Q('financially',4,1,'A project may be useful but financially?','too costly to sustain','made of water','without any possible budget','too costly to sustain','financially 描述项目资金和成本状况。')]});
D('financier',{etymology:E('Financier came through French from financer, related to finance. It especially names a person supplying or managing capital on a large scale.','financier'),contexts:[C('financier.s1','铁路投资','A private financier supplied capital for the railway after several banks declined to fund it.','几家银行拒绝资助铁路后，一位私人金融家提供了资本。','A private financier supplied capital / for the railway / after several banks declined to fund it.','financier 尤指大型融资活动中的出资人。','提供铁路建设资本的人符合金融家义。')],mistakes:[M('The financier supplied no money and played no part in funding the railway.','The financier supplied capital to help fund the railway.','完全未参与筹资的人不符合 financier 的定义。')],quiz:[Q('financier',1,1,'A financier is likely to?','provide or arrange substantial capital','repair a sail','translate a poem','provide or arrange substantial capital','financier 尤指提供或安排大笔资金者。'),Q('financier',2,1,'A financier backed a bridge project by providing?','financial support','a weather report','stone blocks only','financial support','资金支持是 financier 的典型活动。'),Q('financier',3,1,'Choose the natural phrase.','a railway financier','a railway finchier','a financier of rain','a railway financier','financier 可修饰铁路，指铁路融资者。'),Q('financier',4,1,'A financier is involved in?','supplying or managing finance','selling groceries only','conducting trains','supplying or managing finance','financier 与融资和资本有关。')]});
D('financing',{etymology:E('Financing is the -ing noun from finance, borrowed through French financer. It names providing money for a business, purchase, or public project.','financing'),contexts:[C('financing.s1','桥梁预算','Financing for the bridge remains uncertain because the city has approved the design but secured neither loans nor grants.','桥梁融资仍不确定，因为市政府虽已批准设计，却未落实贷款或拨款。','Financing for the bridge remains uncertain / because the city approved the design / but secured neither loans nor grants.','financing 是不可数名词，常接 for 表用途。','资金来源尚未落实，符合融资义。')],mistakes:[M('The bridge had secure financing because no lender or investor had agreed to provide money.','The bridge lacked secure financing because no lender or investor had agreed to provide money.','无人承诺出资，说明缺少融资。')],quiz:[Q('financing',1,1,'Financing a factory means?','providing the money to build or operate it','painting its walls','choosing its logo','providing the money to build or operate it','financing 是为项目提供资金。'),Q('financing',2,1,'A project lacks financing when?','its required money is not secured','its paint is drying','its map is complete','its required money is not secured','未落实所需资金即缺少融资。'),Q('financing',3,1,'Choose the natural phrase.','financing for the project','financing beneath the project','financing of to project','financing for the project','可说 financing for a project。'),Q('financing',4,1,'Which is project financing?','a loan for construction costs','a photo of the finished bridge','a timetable without a budget','a loan for construction costs','工程贷款是融资来源。')]});
D('finch',{etymology:E('Finch is recorded in Old English as finc; its deeper Germanic origin is uncertain. It names small seed-eating birds and the Galápagos birds known as Darwin finches.','finch'),contexts:[C('finch.s2','进化研究','Researchers compared the beaks of Darwin finches and found different average shapes among birds feeding on different foods.','研究人员比较达尔文雀的喙，发现食物不同的鸟类平均喙形也有差异。','Researchers compared the beaks of Darwin finches / and found different average shapes / among birds feeding on different foods.','Darwin finches 指加拉帕戈斯雀鸟。','比较喙形和食物对应进化研究义 s2。')],mistakes:[M('Researchers called the Galápagos birds Darwin finches but found that all species had identical beaks.','Researchers called the Galápagos birds Darwin finches and compared how their beaks varied.','喙形差异是研究重点，说完全相同与语境矛盾。')],quiz:[Q('finch',1,1,'A typical finch has a short thick beak for?','eating seeds','filtering seawater','tearing cloth','eating seeds','一般 finch 以种子为食。'),Q('finch',2,2,'Darwin finches are studied for?','evolution and beak variation','printing technology','deep-sea navigation','evolution and beak variation','达尔文雀在进化研究中著名。'),Q('finch',3,1,'Which fits the source description of a finch?','a small seed-eating bird','a whale without a beak','an underground mammal','a small seed-eating bird','小型、食种子的鸟符合一般义。'),Q('finch',4,2,'Comparing Darwin finches’ beaks can illuminate?','adaptation and evolution','the age of a paper book','how mammals breathe','adaptation and evolution','其喙形差异可用于研究适应与进化。')]});
D('finding',{etymology:E('Finding combines find and -ing. In research and legal use it commonly names a conclusion established by an inquiry.','finding'),contexts:[C('finding.s1','检查结论','The inspection’s main finding was that the cracked beam had been overloaded for months, supported by photos and the maintenance log.','检查的主要结论是开裂横梁已超负荷数月，照片和维修日志为此提供了依据。','The inspection’s main finding was that the cracked beam had been overloaded for months / supported by photos and the maintenance log.','finding 指调查确立的结果或结论。','证据支持的检查结论正是研究结果义。')],mistakes:[M('The inspectors found the beam fractured but reported a finding that it was completely safe.','The inspectors found the beam fractured and reported a finding that it was unsafe.','已断裂却称完全安全与检查证据矛盾。')],quiz:[Q('finding',1,1,'A study’s finding is?','a result or conclusion it establishes','the building where it took place','a guess made before research','a result or conclusion it establishes','finding 指调查得出的结果。'),Q('finding',2,1,'A court finding of fact is based on?','evidence in the case','the courtroom colour','an unrelated diary','evidence in the case','司法事实认定依据案件证据。'),Q('finding',3,1,'Which uses finding as a research result?','The survey’s finding was that bus use increased.','She was finding a glove under the chair.','The office is finding down the road.','The survey’s finding was that bus use increased.','调查所得结论是名词 finding 的研究义。'),Q('finding',4,1,'A report with several findings contains?','results established through investigation','random page decorations','printing tools','results established through investigation','findings 是研究或调查所得结果。')]});
D('finely',{etymology:E('Finely is formed from fine plus -ly. Fine came through French from Latin finis “end, limit,” and developed senses of narrowness and delicacy.','finely'),contexts:[C('finely.s1','烹饪','Add the finely chopped parsley after the soup comes off the heat so its small pieces keep their aroma.','汤离火后再加入切得很细的欧芹，使细碎叶片保留香气。','Add the finely chopped parsley / after the soup comes off the heat / so its small pieces keep their aroma.','finely 修饰 chopped，说明切得细碎。','欧芹被切成小粒，符合 finely 的细碎义。')],mistakes:[M('The recipe called for finely chopped onion, so the cook left it whole and uncut.','The recipe called for roughly chopped onion, so the cook left it whole and uncut.','整颗未切的洋葱不是 finely chopped。')],quiz:[Q('finely',1,1,'Finely chopped garlic is in?','small pieces','one untouched bulb','long branches','small pieces','finely chopped 指切得细碎。'),Q('finely',2,1,'A finely tuned instrument is adjusted?','with precision','without testing','into a larger size','with precision','finely 也可指精确细致地调整。'),Q('finely',3,1,'Choose the natural phrase.','finely ground pepper','finely huge pepper','groundly fine pepper','finely ground pepper','finely 修饰 ground 表示研磨成细粉。'),Q('finely',4,1,'A finely detailed pattern has?','many small careful features','no features','one broad colour block','many small careful features','finely detailed 表示细节精致。')]});
D('finesse',{etymology:E('Finesse came through French finesse “subtlety,” from fin “fine.” As a noun it means tactful skill; as a verb it means handling a difficulty skillfully.','finesse'),contexts:[C('finesse.s2','外交谈判','The envoy finessed the awkward question by acknowledging the concern and returning to the agreed timetable.','特使先承认对方关切，再回到商定时间表，巧妙处理了那个棘手问题。','The envoy finessed the awkward question / by acknowledging the concern / and returning to the agreed timetable.','finesse 在此作及物动词，表示巧妙处理。','特使灵活化解问题，符合动词义 s2。')],mistakes:[M('The envoy finessed the sensitive question by answering bluntly and starting a public argument.','The envoy finessed the sensitive question by replying tactfully and redirecting the discussion.','粗暴回答并引发争吵不属于巧妙、得体的处理。')],quiz:[Q('finesse',1,1,'A negotiator with finesse shows?','subtle skill and tact','careless force','no judgment','subtle skill and tact','s1 指细腻、得体的技巧。'),Q('finesse',2,2,'To finesse an awkward question is to?','handle it skillfully, perhaps indirectly','repeat it louder','answer only with numbers','handle it skillfully, perhaps indirectly','s2 表示巧妙处理难题。'),Q('finesse',3,1,'Which task needs finesse?','mediating a delicate disagreement','counting identical boxes','opening an unlocked door','mediating a delicate disagreement','调停敏感分歧需要 tact。'),Q('finesse',4,2,'Choose the verb use.','She finessed the objection.','Her finesse impressed us.','The finesse is on the desk.','She finessed the objection.','finessed 作动词表示巧妙处理。')]});
D('fingerboard',{etymology:E('Fingerboard combines finger and board. It names the flat surface on a string instrument’s neck where fingers press the strings to change pitch.','fingerboard'),contexts:[C('fingerboard.s1','小提琴','The violinist moved her hand up the fingerboard to reach higher notes, pressing each string at a precise point.','小提琴手把手沿指板上移以演奏更高音，并在准确位置按弦。','The violinist moved her hand up the fingerboard / to reach higher notes / pressing each string at a precise point.','fingerboard 是琴颈上按弦的平面。','手指在指板上改变弦长来演奏音高，符合定义。')],mistakes:[M('The violinist pressed the bow against the fingerboard to change pitch and never touched a string.','The violinist pressed the strings against the fingerboard with her fingers to change pitch.','改变音高需用手指在指板处按弦。')],quiz:[Q('fingerboard',1,1,'On a guitar, a player presses strings against the?','fingerboard','bow hair','music stand','fingerboard','指板是手指按弦的平面。'),Q('fingerboard',2,1,'Moving along a fingerboard changes string?','length and pitch','colour and weight','number and material','length and pitch','按弦位置改变有效弦长及音高。'),Q('fingerboard',3,1,'Where is a violin’s fingerboard?','on its neck beneath the strings','on the bow','inside the case','on its neck beneath the strings','指板位于琴颈上、琴弦下方。'),Q('fingerboard',4,1,'A musician moves along the fingerboard to?','stop strings at different positions','tighten the bow hair','open the case','stop strings at different positions','不同按弦位置产生不同音高。')]});
D('fingertip',{etymology:E('Fingertip combines finger and tip. Literally it is the extreme end of a finger; at one’s fingertips figuratively means readily available.','fingertip'),contexts:[C('fingertip.s1','健康检查','The nurse checked the patient’s fingertip for colour and warmth after the cold walk.','寒冷天气步行后，护士检查了患者指尖的颜色和温度。','The nurse checked the patient’s fingertip / for colour and warmth / after the cold walk.','fingertip 指手指最末端。','检查手指末端的颜色、温度是身体部位义。')],mistakes:[M('The ring was measured at the fingertip, the broad joint in the middle of the finger.','The ring was measured at the finger joint; the fingertip is the very end.','手指中间的关节不是 fingertip。')],quiz:[Q('fingertip',1,1,'A fingertip is?','the very end of a finger','the elbow','the palm centre','the very end of a finger','指尖是手指最末端。'),Q('fingertip',2,1,'Touching a screen with a fingertip uses?','one finger’s end','the forearm','the back of the head','one finger’s end','身体字面义指手指末端。'),Q('fingertip',3,1,'“At her fingertips” figuratively means?','readily available to her','far beyond reach','written on her shoes','readily available to her','该短语表示资源随手可得。'),Q('fingertip',4,1,'A paper cut on a fingertip is on?','the end part of a finger','the shoulder','the heel','the end part of a finger','fingertip 指手指的末端。')]});
D('finitude',{etymology:E('Finitude combines finite and -itude, ultimately related to Latin finis “end, limit.” It denotes the condition of being bounded or having an end.','finitude'),contexts:[C('finitude.s1','哲学讨论','The chapter reflects on the finitude of one human life by contrasting brief personal memories with the city’s centuries-old walls.','这一章把短暂的个人记忆与城市数百年的城墙对照，思考人的生命有限性。','The chapter reflects on the finitude of one human life / by contrasting brief memories / with the city’s centuries-old walls.','finitude 是表示有限状态的抽象名词。','短暂人生与长存城墙形成对比，体现生命有尽头。')],mistakes:[M('The essay praised the finitude of an endless universe with no boundary or limit.','The essay questioned whether the universe has finitude, meaning an end or limit.','没有任何边界或尽头的状态与 finitude 相反。')],quiz:[Q('finitude',1,1,'Human finitude refers to?','limited duration','endless existence','lack of all boundaries','limited duration','finitude 表示有限、有尽头。'),Q('finitude',2,1,'A philosopher discussing finitude considers?','limits and endings','book prices','room colours','limits and endings','该抽象名词指有限性。'),Q('finitude',3,1,'Which is closest to finitude?','limitedness','infinity','immortality','limitedness','finitude 与有限性相近。'),Q('finitude',4,1,'Mortality illustrates finitude because?','a human life has an end','people have unlimited time','mortality is furniture','a human life has an end','生命会终结，体现有限状态。')]});
D('fiord',{etymology:E('Fiord is a variant spelling of fjord, borrowed from Norwegian fjord and related to Old Norse fjǫrðr. It names a deep sea inlet carved by a glacier.','fiord'),contexts:[C('fiord.s1','冰川地貌','The survey boat followed the fiord inland between steep rock walls, where a glacial valley below sea level had filled with seawater.','测量船沿峡湾驶向内陆，两侧岩壁陡峭；低于海平面的冰川谷地已灌满海水。','The survey boat followed the fiord inland / between steep rock walls / where a glacial valley below sea level had filled with seawater.','fiord 与 fjord 为同一地貌的变体拼法。','冰川刻出的深谷被海水淹没，构成峡湾。')],mistakes:[M('The guide called a shallow inland desert pond a fiord despite its lack of a sea inlet or steep glacial valley.','The guide called the deep, steep-sided sea inlet a fiord.','内陆浅池不具峡湾的海湾和冰川谷地特征。')],quiz:[Q('fiord',1,1,'A fiord is typically carved by?','glacial erosion','a dust storm','a river delta only','glacial erosion','峡湾由冰川侵蚀形成。'),Q('fiord',2,1,'What commonly borders a fiord?','steep sides of a glacial valley','flat desert dunes','a coral ring only','steep sides of a glacial valley','峡湾两侧通常陡峭。'),Q('fiord',3,1,'Fiord is a variant of?','fjord','field','firn','fjord','fiord 是 fjord 的拼法变体。'),Q('fiord',4,1,'Which landscape is a fiord?','a sea-filled glacial valley reaching inland','a shallow field pond','a dry canyon far from the sea','a sea-filled glacial valley reaching inland','峡湾是海水深入陆地的冰川谷地。')]});
D('fir',{etymology:E('Fir is an old Germanic tree name recorded in Old English; its exact early path is uncertain. It usually refers to evergreen conifers in the genus Abies.','fir'),contexts:[C('fir.s1','林木识别','The ranger recognized the fir by its flat needles and upright cones, then marked healthy trees for seed collection.','护林员根据扁平针叶和直立球果认出冷杉，并标记了健康树木以便采种。','The ranger recognized the fir by its flat needles and upright cones / then marked healthy trees / for seed collection.','fir 指 Abies 属常绿冷杉。','针叶和球果形态符合冷杉特征。')],mistakes:[M('The botanist identified the evergreen tree with needles and upright cones as a deciduous oak.','The botanist identified the evergreen tree with needles and upright cones as a fir.','针叶常绿树并非落叶栎树。')],quiz:[Q('fir',1,1,'A fir is an evergreen?','coniferous tree','annual herb','fruit vine','coniferous tree','fir 是常绿针叶树。'),Q('fir',2,1,'Which supports identifying an Abies fir?','upright cones on its branches','apples each summer','leaves shed each winter','upright cones on its branches','冷杉球果常直立生长。'),Q('fir',3,1,'Fir branches may be cut for?','winter decorations','printing currency only','underwater breathing','winter decorations','冷杉枝条可用于冬季装饰。'),Q('fir',4,1,'Choose the natural phrase.','a fir forest','a fin forest','a fir of two hours','a fir forest','fir 可修饰 forest，构成“冷杉林”。')]});
D('fireball',{etymology:E('Fireball combines fire and ball. It names a round mass of flame and, in astronomy, an exceptionally bright meteor.','fireball'),contexts:[C('fireball.s1','夜空观测','A bright fireball crossed the night sky for several seconds before vanishing beyond the hills.','一颗明亮的火流星划过夜空数秒，随后消失在山后。','A bright fireball crossed the night sky / for several seconds / before vanishing beyond the hills.','fireball 在天文语境中可指明亮流星。','短暂明亮划过夜空的天体符合流星义。')],mistakes:[M('Astronomers called the dark, motionless object with no visible light a fireball.','Astronomers called the bright meteor that flashed across the sky a fireball.','黑暗且静止的物体不符合明亮流星义。')],quiz:[Q('fireball',1,1,'An astronomical fireball is?','a very bright meteor','a planet in a stable orbit','a dark cloud','a very bright meteor','天文义 fireball 指特别明亮的流星。'),Q('fireball',2,1,'A fireball from a blast is?','a roughly round mass of flame','a pool of water','frozen soil','a roughly round mass of flame','字面义指球状火焰。'),Q('fireball',3,1,'Which report describes a sky fireball?','A bright object flashed across the night.','A dim star stayed fixed all year.','A cloud formed indoors.','A bright object flashed across the night.','明亮天体划过夜空符合流星火球义。'),Q('fireball',4,1,'The compound fireball combines?','fire and ball','fir and board','fire and bell','fire and ball','该词由 fire 与 ball 构成。')]});
D('firefly',{etymology:E('Firefly combines fire and fly, named for the insect’s intermittent glowing abdomen. A firefly is a beetle, not a true fly.','firefly'),contexts:[C('firefly.s1','夏夜观察','At dusk, fireflies flashed above the wet grass, and the children counted the pauses between each insect’s signals.','黄昏时萤火虫在湿草上方闪烁，孩子们数着每只昆虫光信号之间的间隔。','At dusk / fireflies flashed above the wet grass / and the children counted the pauses / between each insect’s signals.','firefly 是腹部能间歇发光的夜行甲虫。','夜间闪烁发光的昆虫符合萤火虫义。')],mistakes:[M('The naturalist classified a daytime butterfly with no glowing abdomen as a firefly.','The naturalist classified the glowing night beetle as a firefly.','萤火虫是夜间发光甲虫，不是普通蝴蝶。')],quiz:[Q('firefly',1,1,'A firefly is a glowing?','beetle','mammal','flowering plant','beetle','萤火虫属于发光甲虫。'),Q('firefly',2,1,'Why is the insect called a firefly?','its pulsing light resembles a tiny fire','it lives inside fireplaces','it eats flames','its pulsing light resembles a tiny fire','名字来自腹部闪光像小火点。'),Q('firefly',3,1,'When are fireflies often easiest to see?','after dusk','at noon only','deep underground','after dusk','黄昏后容易看到它们闪光。'),Q('firefly',4,1,'A firefly’s light appears as?','brief repeated flashes','a permanent wing flame','underwater glow only','brief repeated flashes','萤火虫常间歇性闪光。')]});
D('fireproof',{etymology:E('Fireproof combines fire and proof in the sense “resistant to.” It describes something made not to catch fire readily or burn through easily.','fireproof'),contexts:[C('fireproof.s1','档案保管','The archive stored paper records in a fireproof cabinet, while keeping digital copies in another building.','档案馆把纸质记录存入防火柜，同时在另一栋楼保存数字副本。','The archive stored paper records in a fireproof cabinet / while keeping digital copies / in another building.','fireproof 作定语，表示防火、耐火。','柜子用于降低纸档案遭火灾损毁的风险。')],mistakes:[M('The label called the cardboard box fireproof, but a small spark immediately set it alight.','The label called the cardboard box highly flammable because a small spark immediately set it alight.','一遇火花就燃烧的纸板箱不具防火性。')],quiz:[Q('fireproof',1,1,'A fireproof cabinet is designed to?','resist fire','make contents burn faster','produce smoke','resist fire','fireproof 表示防火或耐火。'),Q('fireproof',2,1,'Why store records in a fireproof safe?','to reduce fire damage','to absorb water','to fade ink','to reduce fire damage','耐火箱用于保护文件免受火灾。'),Q('fireproof',3,1,'Which is fireproof?','a tested fire-resistant box','dry straw that ignites easily','an open flame','a tested fire-resistant box','耐火储物箱符合定义。'),Q('fireproof',4,1,'The -proof part suggests?','resistant to fire','made of fire','used after fire only','resistant to fire','proof 此处表示能抵御某种影响。')]});
D('firewood',{etymology:E('Firewood combines fire and wood. It names logs and smaller pieces prepared to burn as fuel.','firewood'),contexts:[C('firewood.s1','冬季储柴','Before the frost, the family stacked dry firewood beneath the shed roof with gaps for air to circulate.','初霜前，一家人把干木柴堆在棚顶下，并留空隙通风。','Before the frost / the family stacked dry firewood beneath the shed roof / with gaps for air to circulate.','firewood 通常作不可数名词，泛指燃料木材。','晾干并堆存以便烧火，符合木柴义。')],mistakes:[M('They bought wet firewood that could not burn safely to heat the stove.','They bought dry firewood to heat the stove safely.','湿柴不适合安全有效地燃烧取暖。')],quiz:[Q('firewood',1,1,'Firewood is wood prepared for?','burning as fuel','making glass windows','printing maps','burning as fuel','firewood 是烧火用的木柴。'),Q('firewood',2,1,'A family stores firewood to?','heat a stove or fireplace','pour into a kettle as water','make a curtain','heat a stove or fireplace','木柴用于炉火取暖。'),Q('firewood',3,1,'Choose the natural phrase.','a bundle of firewood','a cup of firewood','a firewood of advice','a bundle of firewood','bundle 可量化一捆木柴。'),Q('firewood',4,1,'Why leave gaps in a firewood pile?','to help the logs dry','to make leaves grow','to stop it being wood','to help the logs dry','通风有助于木柴干燥。')]});
D('firn',{etymology:E('Firn is an Alpine snow term related to German Firn for old or last-season snow; the deeper history is uncertain. It describes granular snow that survives summer and compacts toward glacier ice.','firn'),contexts:[C('firn.s1','冰川测量','Above the crevasses, the team drilled through firn that had survived summer but had not yet become solid glacier ice.','在冰裂隙上方，测量队钻穿了过夏后仍在、但尚未变成坚实冰川冰的粒雪。','Above the crevasses / the team drilled through firn / that had survived summer / but had not yet become solid glacier ice.','firn 指积雪向冰川冰转化过程中尚呈颗粒状的阶段。','过夏的颗粒雪尚未完全压实成冰川冰，符合定义。')],mistakes:[M('The glaciologist called freshly fallen snow firn although it had not survived summer or compacted.','The glaciologist called granular snow that had survived summer firn.','刚落下且未经历压实的雪还不是 firn。')],quiz:[Q('firn',1,1,'Firn is snow that?','survived summer and is compacting toward ice','fell moments ago','melted into a lake','survived summer and is compacting toward ice','firn 是过夏后逐渐压实的粒雪。'),Q('firn',2,1,'Where might a glaciologist find firn?','on an upper glacier accumulation zone','in a tropical greenhouse','in a city basement','on an upper glacier accumulation zone','firn 出现在冰川积累区。'),Q('firn',3,1,'Firn differs from fresh snow because it?','has persisted and become granular','is warm rain','has no ice crystals','has persisted and become granular','它经过时间和压实形成颗粒状。'),Q('firn',4,1,'Choose the likely sequence.','fresh snow, firn, glacier ice','ice, firewood, snow','rain, sand, firn','fresh snow, firn, glacier ice','积雪逐步压实为 firn，再形成冰川冰。')]});
D('first-aid',{etymology:E('First-aid combines first, meaning initial in time, and aid, meaning help. It refers to immediate assistance given to an injured or suddenly ill person before fuller medical care is available.','first-aid'),contexts:[C('first-aid.s1','急救准备','Every workshop keeps a first-aid kit beside the entrance so staff can treat minor injuries while waiting for medical help.','每间车间都在入口旁备有急救箱，以便员工在等待医疗救助时处理轻伤。','Every workshop keeps a first-aid kit beside the entrance / so staff can treat minor injuries / while waiting for medical help.','first-aid 作定语修饰 kit，指用于即时救助的急救用品。','急救箱用于专业医疗到来前的初步处置，符合义项。')],mistakes:[M('The label called the delayed surgery performed days later first-aid, although no immediate help was given after the accident.','The label called the immediate wound care given after the accident first-aid.','数日后手术不是事故发生后立即提供的初步救助。')],quiz:[Q('first-aid',1,1,'First-aid is help given?','immediately after injury or sudden illness','only after a long-term recovery','to repair a machine','immediately after injury or sudden illness','first-aid 指即时初步救助。'),Q('first-aid',2,1,'A first-aid kit usually contains supplies for?','basic immediate care','cooking a full meal','painting a wall','basic immediate care','急救箱装有处理轻伤等的基础用品。'),Q('first-aid',3,1,'Which phrase is standard?','a first-aid kit','a first-aid of water','a kit first-aidly','a first-aid kit','常用搭配为 first-aid kit。'),Q('first-aid',4,1,'First aid normally comes before?','more complete medical treatment','the injury occurs','the patient is born','more complete medical treatment','急救通常是正式、全面医疗前的即时处理。')]});
D('fisherman',{etymology:E('Fisherman combines fish and man, with fisherman recorded in English for a person who catches fish, often as a livelihood.','fisherman'),contexts:[C('fisherman.s1','水坝计划','Local fishermen opposed the dam because its new flow schedule would leave their traditional fishing grounds too shallow in spring.','当地渔民反对水坝，因为新的水流安排会使传统渔场在春季水位过浅。','Local fishermen opposed the dam / because its new flow schedule / would leave their traditional fishing grounds too shallow in spring.','fisherman 指捕鱼者；复数 fishermen 是不规则复数。','捕鱼为生或从事捕鱼的人受到渔场变化影响，符合义项。')],mistakes:[M('The fisherman earned his living by growing wheat and never caught or sold any fish.','The farmer earned his living by growing wheat and never caught or sold any fish.','只种小麦的人是 farmer，不是 fisherman。')],quiz:[Q('fisherman',1,1,'A fisherman is someone who?','catches fish, often for a living','repairs only aircraft engines','raises wheat in a field','catches fish, often for a living','fisherman 指捕鱼的人，尤指以捕鱼为业者。'),Q('fisherman',2,1,'The plural of fisherman is?','fishermen','fishermans','fishermen’s','fishermen','fisherman 的复数是不规则形式 fishermen。'),Q('fisherman',3,1,'Which person is most likely a fisherman?','a worker bringing a catch back to port','a botanist pruning roses','a miner sorting coal','a worker bringing a catch back to port','捕获并带鱼回港的人从事捕鱼。'),Q('fisherman',4,1,'A fisherman’s work is most directly connected with?','catching fish','designing a bridge','printing books','catching fish','其职业与捕鱼直接相关。')]});
D('fishery',{etymology:E('Fishery is formed from fish and -ery, a suffix used for an activity, industry, or place. It can mean the fishing industry or a managed area where fish are caught or raised.','fishery'),contexts:[C('fishery.s1','沿海管理','The coastal fishery collapsed after years of overfishing, so regulators closed several grounds and limited the seasonal catch.','多年过度捕捞后，沿海渔业衰退，因此监管部门关闭了数处渔场并限制季节性捕获量。','The coastal fishery collapsed after years of overfishing / so regulators closed several grounds / and limited the seasonal catch.','fishery 可指渔业产业或受管理的渔场。','关闭渔场并设捕捞限额体现产业和捕捞区域义。')],mistakes:[M('The fishery thrived because every fish stock disappeared and no fishing could take place.','The fishery collapsed because fish stocks disappeared and no sustainable catch remained.','鱼群消失、无法持续捕捞意味着渔业衰退而非兴旺。')],quiz:[Q('fishery',1,1,'A fishery may refer to?','the fishing industry or a managed fishing area','a forest nursery only','a fishing boat’s engine','the fishing industry or a managed fishing area','fishery 有产业和渔场两义。'),Q('fishery',2,1,'Regulators close a fishery mainly to?','protect fish stocks from overfishing','increase the number of roads','stop rain from falling','protect fish stocks from overfishing','关闭捕捞水域有助于鱼群恢复。'),Q('fishery',3,1,'Which phrase is natural?','a coastal fishery','a coastal fishery of wheat','a fishery flight schedule','a coastal fishery','coastal fishery 指沿海渔场或渔业。'),Q('fishery',4,1,'A fishery collapse would most likely affect?','people and businesses relying on catches','the colour of mountain snow','a theatre’s seating plan','people and businesses relying on catches','渔业衰退会影响依赖渔获的群体。')]});
D('fishing',{etymology:E('Fishing is formed from fish plus -ing. As a noun it names the activity or industry of trying to catch fish.','fishing'),contexts:[C('fishing.s1','水库规定','Fishing is prohibited in the reservoir during the breeding season, when spawning fish need undisturbed water.','繁殖季节禁止在水库捕鱼，此时产卵的鱼需要不受干扰的水域。','Fishing is prohibited in the reservoir / during the breeding season / when spawning fish need undisturbed water.','fishing 作名词表示捕鱼或钓鱼活动。','季节性禁捕规则针对捕捞活动。')],mistakes:[M('Fishing was banned to protect spawning fish, so the notice invited visitors to catch as many as they liked.','Fishing was banned to protect spawning fish, so the notice asked visitors not to catch them.','禁捕规则与邀请随意捕捉相矛盾。')],quiz:[Q('fishing',1,1,'Fishing is the activity of trying to?','catch fish','plant wheat','repair a net without using it','catch fish','fishing 指钓鱼或捕鱼活动。'),Q('fishing',2,1,'A ban on fishing means people may not?','catch fish there','watch the water','walk on the bank','catch fish there','禁 fishing 即禁止捕鱼。'),Q('fishing',3,1,'Which phrase is idiomatic?','go fishing','go fishery','go fished','go fishing','英语常说 go fishing。'),Q('fishing',4,1,'Commercial fishing is done mainly to?','catch fish as an industry','teach a bird to fly','measure river stones','catch fish as an industry','commercial 修饰 fishing，说明产业性捕捞。')]});
D('fishy',{etymology:E('Fishy is formed from fish plus -y. It first describes a fishlike smell or taste; figuratively it means suspicious, and it can also describe a fixed, lifeless stare.','fishy'),contexts:[C('fishy.s2','可疑交易','The invoice looked fishy because its account number changed twice and the supplier refused to confirm the new bank details.','这张发票看起来蹊跷，因为账户号码改了两次，供应商还拒绝确认新的银行信息。','The invoice looked fishy / because its account number changed twice / and the supplier refused to confirm the new bank details.','fishy 作表语形容词，口语中表示可疑。','账户反复变更且供应商拒绝核实，确实令人怀疑，符合 s2。')],mistakes:[M('The invoice seemed fishy, but every payment detail matched the verified supplier records and had been independently confirmed.','The invoice seemed legitimate because every payment detail matched verified supplier records.','全部核验无误与可疑的判断不一致。')],quiz:[Q('fishy',1,1,'A fishy smell is?','strongly like fish','freshly floral','completely odourless','strongly like fish','s1 指鱼腥味或鱼腥气味。'),Q('fishy',2,2,'A fishy explanation sounds?','suspicious and hard to believe','fully verified and ordinary','pleasantly fragrant','suspicious and hard to believe','s2 比喻表示可疑、蹊跷。'),Q('fishy',3,3,'A fishy stare is described as?','fixed and lifeless','brightly smiling','closed in sleep','fixed and lifeless','s3 指像死鱼眼一样呆滞的眼神。'),Q('fishy',4,2,'Which situation seems fishy?','a seller changes payment accounts and avoids confirmation','a receipt matches the bank statement','a shop posts its normal opening hours','a seller changes payment accounts and avoids confirmation','账户频繁更改且拒绝核实，显得可疑。')]});
D('fission',{etymology:E('Fission comes through French from Latin fissio “a splitting,” from findere “to split.” It names the division of an atomic nucleus or a cell into two.','fission'),contexts:[C('fission.s1','核物理','In the reactor, nuclear fission releases energy when a heavy atomic nucleus splits and emits neutrons that can trigger further reactions.','在反应堆中，重原子核分裂并释放中子、触发后续反应时，核裂变会释放能量。','In the reactor / nuclear fission releases energy / when a heavy atomic nucleus splits / and emits neutrons that can trigger further reactions.','nuclear fission 是固定科学术语；fission 指分裂。','重原子核分裂释放能量，符合原子核裂变义。')],mistakes:[M('The physicist described fission as two light nuclei joining to form a heavier nucleus.','The physicist described fusion as two light nuclei joining to form a heavier nucleus.','轻核结合是 fusion；fission 指核分裂。')],quiz:[Q('fission',1,1,'Nuclear fission occurs when an atomic nucleus?','splits into smaller parts','joins another nucleus','freezes into ice','splits into smaller parts','fission 指原子核分裂。'),Q('fission',2,1,'Cell fission produces?','two cells from one','one cell from two','a stone from water','two cells from one','细胞分裂可由一个细胞分成两个。'),Q('fission',3,1,'Which term contrasts with nuclear fission?','fusion','filtration','fidelity','fusion','fusion 是核聚变，与裂变相对。'),Q('fission',4,1,'A fission reaction may release?','neutrons and energy','paper clips','only sound','neutrons and energy','核裂变会释放能量并可产生中子。')]});
D('fittingly',{etymology:E('Fittingly is the adverb from fitting, the -ing form of fit, plus -ly. It means in a way appropriate to a person or occasion.','fittingly'),contexts:[C('fittingly.s1','纪念开幕','Fittingly, the new bridge was opened by the engineer who had designed it and spent twenty years campaigning for its construction.','新桥由设计它并为建设奔走二十年的工程师主持开通，确实再合适不过。','Fittingly / the new bridge was opened by the engineer / who had designed it / and spent twenty years campaigning for its construction.','句首 fittingly 是评注副词，说明事件与情境相称。','设计者主持开通仪式十分契合场合，体现适当地、名副其实地。')],mistakes:[M('Fittingly, the retired founder was excluded from the ceremony held specifically to honour her life’s work.','Fittingly, the retired founder was invited to the ceremony held to honour her life’s work.','专门表彰创始人的仪式却排除她本人，难称合宜。')],quiz:[Q('fittingly',1,1,'Fittingly, the award went to the person who?','had done the work being honoured','had never heard of the project','was chosen at random by a stranger','had done the work being honoured','fittingly 表示与场合或人物相称。'),Q('fittingly',2,1,'A fittingly chosen song is?','appropriate for the occasion','unrelated to the event','impossible to hear','appropriate for the occasion','该副词表示选择得恰当。'),Q('fittingly',3,1,'Choose the natural sentence.','Fittingly, the school named the library after its donor.','Fittingly, the library named the school after under it.','Fittingly named after, the donor library.','Fittingly, the school named the library after its donor.','为捐赠者命名图书馆与其贡献相称。'),Q('fittingly',4,1,'If a farewell ends fittingly, it ends?','in a way that suits the occasion','in a way that contradicts it','without anyone noticing the event','in a way that suits the occasion','fittingly 表示恰当地、合乎情境地。')]});
D('flabby',{etymology:E('Flabby is a colloquial adjective recorded in English by the eighteenth century; its exact origin is uncertain. It describes loose soft flesh and, figuratively, weak or ineffectual writing or thought.','flabby'),contexts:[C('flabby.s2','论证评审','The reviewer called the report’s reasoning flabby because it repeated slogans but never connected the evidence to its conclusion.','评论者称报告的论证软弱无力，因为它反复使用口号，却从未把证据与结论联系起来。','The reviewer called the report’s reasoning flabby / because it repeated slogans / but never connected the evidence to its conclusion.','flabby 在此为比喻用法，表示论证乏力、缺乏力度。','证据未能支持结论，体现思维或论述软弱义 s2。')],mistakes:[M('The editor praised the argument as flabby because every claim was clearly supported by strong evidence.','The editor praised the argument as rigorous because every claim was clearly supported by strong evidence.','有力证据支持论点表示严谨，不是 flabby。')],quiz:[Q('flabby',1,1,'Flabby muscles are?','soft and lacking firmness','hard and highly toned','made of stone','soft and lacking firmness','s1 描述松软、缺少紧实感。'),Q('flabby',2,2,'A flabby argument is?','weak and lacking clear force','strongly supported and precise','a type of muscle','weak and lacking clear force','s2 比喻指论证薄弱。'),Q('flabby',3,1,'Which body description fits flabby?','loose soft flesh after little exercise','firm muscles after training','a stiff wooden frame','loose soft flesh after little exercise','形容身体时 flabby 指肌肉松弛。'),Q('flabby',4,2,'A flabby report is most likely criticized for?','vague reasoning with little support','accurate evidence and a clear claim','being printed in blue ink','vague reasoning with little support','论证缺乏力量和清晰度对应 s2。')]});
D('flagella',{etymology:E('Flagella is the Latin plural of flagellum, from flagellum “little whip.” It names the threadlike structures by which certain cells or organisms move.','flagella'),contexts:[C('flagella.s1','细胞运动','Under the microscope, the bacteria rotated their flagella to swim toward nutrients in the surrounding liquid.','在显微镜下，细菌转动鞭毛，游向周围液体中的营养物质。','Under the microscope / the bacteria rotated their flagella / to swim toward nutrients / in the surrounding liquid.','flagella 是 flagellum 的复数形式。','多个鞭毛协助细菌游动，符合定义。')],mistakes:[M('The microbiologist called one threadlike appendage flagella, although the word is plural.','The microbiologist called one threadlike appendage a flagellum.','一个结构用单数 flagellum；flagella 是复数。','grammar')],quiz:[Q('flagella',1,1,'Flagella are?','threadlike structures some cells use for movement','large bones in a bird’s wing','cell walls made of stone','threadlike structures some cells use for movement','flagella 指帮助细胞运动的鞭状结构。'),Q('flagella',2,1,'What is the singular of flagella?','flagellum','flagellae only','flagelliform','flagellum','flagella 是 flagellum 的复数。'),Q('flagella',3,1,'Bacteria may rotate flagella to?','swim through liquid','grow wooden branches','filter sunlight','swim through liquid','鞭毛转动能推动细菌在液体中移动。'),Q('flagella',4,1,'Choose the grammatically correct phrase.','Several flagella propel the cell.','Several flagellum propels the cells.','A flagella propels each cell.','Several flagella propel the cell.','复数主语 flagella 与动词 propel 呼应。')]});
D('flagelliform',{etymology:E('Flagelliform combines flagellum with the Latin-derived form element -form “shaped.” It describes something slender and flexible like a whip or cellular flagellum.','flagelliform'),contexts:[C('flagelliform.s1','昆虫形态','The moth’s flagelliform antennae were long and threadlike, curving gently as it moved through the air.','这种蛾的鞭状触角细长如丝，飞行时轻轻弯曲。','The moth’s flagelliform antennae were long and threadlike / curving gently / as it moved through the air.','flagelliform 是形态形容词，描述像鞭毛一样细长。','细长且柔韧的触角符合鞭毛状义。')],mistakes:[M('The botanist called a thick rigid cube flagelliform even though it was neither slender nor flexible.','The botanist called the slender flexible tendril flagelliform.','粗厚而僵硬的立方体不具鞭状细长形态。')],quiz:[Q('flagelliform',1,1,'A flagelliform antenna is?','slender and whip-shaped','broad and square','short and stone-hard','slender and whip-shaped','flagelliform 指细长、鞭状的形态。'),Q('flagelliform',2,1,'Which object is most plausibly flagelliform?','a long flexible threadlike appendage','a thick cube','a flat circular plate','a long flexible threadlike appendage','细长柔韧的附属物符合该词义。'),Q('flagelliform',3,1,'The suffix-like element -form means?','shaped like','smelling of','located under','shaped like','-form 表示具有某种形状。'),Q('flagelliform',4,1,'A flagelliform structure resembles a?','whip or flagellum','brick wall','closed box','whip or flagellum','构词指形状像鞭毛。')]});
D('flagellum',{etymology:E('Flagellum comes from Latin flagellum “little whip,” a diminutive of flagrum “whip.” In biology it names a long threadlike structure that can propel a cell.','flagellum'),contexts:[C('flagellum.s1','精子细胞','A sperm cell moves through fluid by beating its single flagellum, which acts like a tiny flexible propeller.','精子细胞通过摆动单根鞭毛在液体中移动，这根细长结构像微型柔性推进器。','A sperm cell moves through fluid / by beating its single flagellum / which acts like a tiny flexible propeller.','flagellum 为单数，指一个鞭毛。','摆动鞭毛推动细胞前进，符合生物学义。')],mistakes:[M('The cell moved using one flagella that rotated behind it.','The cell moved using one flagellum that rotated behind it.','one 后需用单数 flagellum；flagella 是复数。','grammar')],quiz:[Q('flagellum',1,1,'A cell’s flagellum can help it?','move through its surroundings','form a hard shell','digest a whole tree','move through its surroundings','鞭毛可推动细胞运动。'),Q('flagellum',2,1,'The plural of flagellum is?','flagella','flagellumses','flagelliform','flagella','flagellum 的常用复数为 flagella。'),Q('flagellum',3,1,'Which description fits a flagellum?','a long threadlike moving structure','a flat stone plate','a round fruit seed','a long threadlike moving structure','鞭毛是细长的鞭状结构。'),Q('flagellum',4,1,'The name flagellum reflects a resemblance to a?','small whip','wooden flagpole','glass flask','small whip','词源的 little whip 对应鞭状外形。')]});
D('flagpole',{etymology:E('Flagpole combines flag and pole. It names the upright pole on which a flag is displayed.','flagpole'),contexts:[C('flagpole.s1','校园升旗','The groundskeeper lowered the flag before the storm and inspected the flagpole for loose bolts.','暴风雨来临前，管理员降下旗帜，并检查旗杆上的螺栓是否松动。','The groundskeeper lowered the flag before the storm / and inspected the flagpole / for loose bolts.','flagpole 指竖立用来挂旗的杆。','旗帜从杆上降下，管理员检查旗杆结构。')],mistakes:[M('The groundskeeper raised the flag on the flagpole, which was a flat sheet hanging from a line and not a pole.','The groundskeeper raised the flag on the flagpole, the upright pole that carries it.','旗杆是杆状支撑物，不是布旗本身。')],quiz:[Q('flagpole',1,1,'A flagpole is used to?','carry or display a flag','hold a fishing net underwater','measure the wind temperature','carry or display a flag','flagpole 是升挂旗帜的杆。'),Q('flagpole',2,1,'A flag is usually attached to a?','flagpole','flagstone','flagella','flagpole','旗帜可固定在 flagpole 上。'),Q('flagpole',3,1,'Choose the correct compound.','The flagpole bent in the wind.','The flagpole was a cloth flag.','The flagpole carried no pole.','The flagpole bent in the wind.','旗杆在风中弯曲，搭配自然。'),Q('flagpole',4,1,'Which is not a flagpole?','the flag fabric itself','the upright support for a flag','a pole outside a school','the flag fabric itself','旗帜本身是布，不是支撑旗帜的杆。')]});
D('flair',{etymology:E('Flair came through French flair, “scent or instinct,” related to flair “to smell.” English developed the figurative sense of instinctive skill or stylish talent; the deeper French history is uncertain.','flair'),contexts:[C('flair.s1','讲解设计','Nora has a flair for explaining complex diagrams, turning each crowded page into a clear sequence of visual steps.','诺拉很有讲解复杂图表的天赋，能把每一页拥挤的内容转化成清晰的视觉步骤。','Nora has a flair for explaining complex diagrams / turning each crowded page / into a clear sequence of visual steps.','常用结构为 have a flair for + 名词或动名词。','她能巧妙清楚地讲解图表，体现天赋和手腕。')],mistakes:[M('He had a flair for explaining maps, but every explanation confused the audience and hid the route.','He lacked a flair for explaining maps because his explanations confused the audience.','解释总使人困惑与擅长解释相反。')],quiz:[Q('flair',1,1,'A person with a flair for design has?','a natural stylish talent','no interest in design','a broken drawing tool','a natural stylish talent','flair 指做某事的天赋或风格。'),Q('flair',2,1,'Choose the usual pattern.','a flair for languages','a flair on language','a flair at language to','a flair for languages','常说 have a flair for。'),Q('flair',3,1,'A chef adds a dish with flair by?','presenting it with skill and style','forgetting to cook it','serving an empty plate','presenting it with skill and style','flair 体现熟练和风格。'),Q('flair',4,1,'Which person shows a flair for music?','a student who instinctively writes lively melodies','a student who never hears any sound','a student carrying a music stand','a student who instinctively writes lively melodies','自然而有风格的创作体现音乐天赋。')]});
D('flamboyant',{etymology:E('Flamboyant came from French flamboyant, literally “flaming,” related to flambe “flame.” It describes vivid colour or conspicuously bold behaviour.','flamboyant'),contexts:[C('flamboyant.s2','舞台风格','The flamboyant singer wore a silver cape and entered the stage beneath a shower of lights, clearly enjoying the audience’s attention.','这位举止张扬的歌手披着银色斗篷，在灯光中走上舞台，显然很享受观众的关注。','The flamboyant singer wore a silver cape / and entered the stage beneath a shower of lights / clearly enjoying the audience’s attention.','flamboyant 修饰 singer，描述大胆醒目、引人注目的举止。','服饰和舞台行为都刻意吸引注意，符合 s2。')],mistakes:[M('The flamboyant performer avoided attention, wore plain clothes, and refused to appear on stage.','The flamboyant performer sought attention with bold clothes and a dramatic stage entrance.','刻意避开注意与 flamboyant 的张扬特征相反。')],quiz:[Q('flamboyant',1,1,'A flamboyant dress is?','very bright and eye-catching','plain grey and unnoticed','made only for sleeping','very bright and eye-catching','s1 指色彩艳丽、夺目。'),Q('flamboyant',2,2,'A flamboyant speaker tends to?','behave boldly and attract attention','avoid all public attention','speak only in whispers','behave boldly and attract attention','s2 指举止张扬、引人注目。'),Q('flamboyant',3,1,'Which colour description fits flamboyant?','brilliant purple with gold trim','dull grey without contrast','transparent and invisible','brilliant purple with gold trim','艳丽、醒目的配色符合色彩义。'),Q('flamboyant',4,2,'A flamboyant entrance is likely?','dramatic and designed to be noticed','silent and deliberately hidden','unrelated to the event','dramatic and designed to be noticed','张扬的入场方式意在吸引注意。')]});
D('flaming',{etymology:E('Flaming is the present participle and adjective from flame, ultimately from Latin flamma. It can describe actual burning, fire-bright colour, or an angry quarrel.','flaming'),contexts:[C('flaming.s3','争吵描述','They had a flaming row over the missing funds, with both sides raising their voices and accusing the other of hiding records.','他们为失踪资金激烈争吵，双方都提高嗓门并指责对方隐瞒记录。','They had a flaming row over the missing funds / with both sides raising their voices / and accusing the other of hiding records.','flaming 修饰 row，作口语化强化语表示争吵激烈。','大声互相指责符合 s3 的激烈争吵义。')],mistakes:[M('The two directors had a flaming row but calmly agreed on every point without raising their voices.','The two directors had a quiet discussion and agreed on every point.','平静一致的讨论与激烈争吵相矛盾。')],quiz:[Q('flaming',1,1,'A flaming log is?','burning with visible flames','frozen solid','painted with water','burning with visible flames','s1 指正冒火焰燃烧。'),Q('flaming',2,2,'A flaming sunset has?','bright red-orange colour','no visible colour','a green metallic surface','bright red-orange colour','s2 比喻颜色像火焰般红橙。'),Q('flaming',3,3,'A flaming row is?','an intense angry argument','a quiet shared meal','a boat race','an intense angry argument','s3 指言辞激烈的争吵。'),Q('flaming',4,1,'Which phrase uses the literal burning sense?','flaming branches fell from the tree','a flaming sunset filled the horizon','they had a flaming argument','flaming branches fell from the tree','真正着火的树枝体现燃烧义。')]});
D('flange',{etymology:E('Flange is an engineering term for a projecting rim or edge, especially one used to strengthen or join parts; its deeper word origin is uncertain.','flange'),contexts:[C('flange.s1','管道维修','The plumber tightened the flange where the pipe met the tank, replacing a worn gasket to prevent another leak.','水管工拧紧了管道与水箱连接处的法兰，并更换了磨损的垫圈以防再次漏水。','The plumber tightened the flange / where the pipe met the tank / replacing a worn gasket / to prevent another leak.','flange 指管、梁或轮上凸出的扁边，常用于连接。','它位于管道连接处并压紧垫圈，符合机械义。')],mistakes:[M('The pipe joint leaked because its flange was a smooth central hole with no projecting rim for the bolts.','The pipe joint leaked because its flange was cracked and could not hold the bolts tightly.','flange 是用于加固或连接的凸缘，不是没有边缘的孔。')],quiz:[Q('flange',1,1,'A pipe flange is a projecting rim used to?','join or strengthen sections','filter drinking water','measure temperature','join or strengthen sections','法兰凸缘用于连接或加固。'),Q('flange',2,1,'Where might a wheel flange be found?','along an edge that helps guide it on a rail','inside a paper envelope','on a flower petal','along an edge that helps guide it on a rail','轮缘可沿边缘引导车轮。'),Q('flange',3,1,'A flange on a pipe may hold?','bolts and a gasket at a joint','a bird’s feather','a glass of milk','bolts and a gasket at a joint','法兰连接处通常用螺栓和垫圈密封。'),Q('flange',4,1,'Which shape best fits a flange?','a flat projecting rim','a perfectly smooth sphere','a loose liquid','a flat projecting rim','flange 是凸出的扁边。')]});
D('flannel',{etymology:E('Flannel came through French flanelle, probably from Welsh gwlanen “woollen cloth.” It is a soft fabric with a slightly fuzzy surface, used for clothing and cloths.','flannel'),contexts:[C('flannel.s1','冬装面料','He chose a grey flannel suit for the cold conference hall because the soft napped cloth was warmer than his summer jacket.','他为寒冷的会议厅选了一套灰色法兰绒西装，因为这种柔软起绒的布料比夏季夹克更暖和。','He chose a grey flannel suit for the cold conference hall / because the soft napped cloth / was warmer than his summer jacket.','flannel 指表面略起绒的软布料。','起绒布料做成冬季西装，符合面料义。')],mistakes:[M('The tailor described the smooth, stiff sheet of metal as flannel.','The tailor described the soft, slightly fuzzy cloth as flannel.','金属片不是柔软起绒的织物。')],quiz:[Q('flannel',1,1,'Flannel is a kind of?','soft cloth with a slightly fuzzy surface','hard transparent glass','metal wire','soft cloth with a slightly fuzzy surface','flannel 是柔软略起绒的织物。'),Q('flannel',2,1,'A flannel shirt is likely to feel?','soft and warm','sharp and metallic','wet and liquid','soft and warm','法兰绒常用于保暖衣物。'),Q('flannel',3,1,'Which item could be made of flannel?','a soft winter suit','a steel bridge bolt','a drinking glass','a soft winter suit','法兰绒可制作西装或衬衫。'),Q('flannel',4,1,'The surface of flannel is often?','slightly fuzzy','perfectly smooth like glass','covered in sharp blades','slightly fuzzy','表面略起绒是其特点。')]});
D('flashbulb',{etymology:E('Flashbulb combines flash and bulb. It names an old-style or single-use camera bulb that produces a brief bright burst of light.','flashbulb'),contexts:[C('flashbulb.s1','老式摄影','The photographer replaced the spent flashbulb before the indoor portrait session because the old camera had no built-in electronic flash.','室内肖像拍摄前，摄影师换掉了用过的闪光灯泡，因为这台旧相机没有内置电子闪光灯。','The photographer replaced the spent flashbulb / before the indoor portrait session / because the old camera had no built-in electronic flash.','flashbulb 指旧式相机中产生瞬间强光的一次性或老式灯泡。','相机需更换已用过的闪光灯泡以照亮室内拍摄。')],mistakes:[M('The photographer reused the same single-use flashbulb for every picture after it had already fired and burned out.','The photographer replaced the single-use flashbulb after it had fired and burned out.','一次性灯泡闪过并烧完后不能重复使用。')],quiz:[Q('flashbulb',1,1,'A flashbulb provides a camera with?','a brief burst of bright light','continuous music','a printed photograph','a brief burst of bright light','flashbulb 为拍摄提供短促强光。'),Q('flashbulb',2,1,'An old camera’s spent flashbulb must be?','replaced before another flash','filled with water','sharpened like a pencil','replaced before another flash','一次性灯泡使用后需更换。'),Q('flashbulb',3,1,'Which context best fits flashbulb?','a photographer taking an indoor picture','a gardener watering a rose','a sailor raising a flag','a photographer taking an indoor picture','该设备用于相机摄影闪光。'),Q('flashbulb',4,1,'A flashbulb differs from a steady lamp because it?','gives a short burst of light','stays dark when activated','records sound only','gives a short burst of light','它提供瞬间而非持续照明。')]});
D('flask',{etymology:E('Flask is an old English word borrowed through Germanic forms, ultimately related to words for a bottle. It can mean a laboratory vessel or a small flat bottle carried for spirits.','flask'),contexts:[C('flask.s1','实验室操作','The chemist poured the measured solution into a conical flask, swirled it gently, and labelled the mixture before heating.','化学家把定量溶液倒进锥形烧瓶，轻轻摇匀，并在加热前给混合液贴上标签。','The chemist poured the measured solution into a conical flask / swirled it gently / and labelled the mixture before heating.','flask 的 s1 是实验室盛液体的细颈玻璃瓶。','锥形瓶盛装并混合溶液，符合实验室容器义。')],mistakes:[M('The chemist stored the solution in a flask made of open cotton cloth that could not hold liquids.','The chemist stored the solution in a glass flask designed to hold liquids.','烧瓶是可盛液体的容器，不是渗漏的布料。')],quiz:[Q('flask',1,1,'A laboratory flask is used to?','hold liquids for experiments','serve as a flagpole','measure a bird’s wings','hold liquids for experiments','s1 指实验室盛液体的玻璃容器。'),Q('flask',2,2,'A pocket flask is traditionally carried to hold?','a strong drink','laboratory sand only','a folded map','a strong drink','s2 指随身携带的小扁酒瓶。'),Q('flask',3,1,'Which phrase fits a laboratory vessel?','a conical flask','a conical finch','a flask of flagpoles','a conical flask','锥形烧瓶是实验室常见器皿。'),Q('flask',4,2,'A traveller takes a small flask in a pocket. It is likely?','a flat bottle for spirits','a large glass lab vessel','a lamp that gives a flash','a flat bottle for spirits','口袋里的小扁瓶符合随身酒瓶义。')]});
D('flatboat',{etymology:E('Flatboat combines flat and boat, named for its broad, flat bottom. Such boats have traditionally carried cargo on rivers and canals.','flatboat'),contexts:[C('flatboat.s1','河运','Flatboats carried grain downstream because their broad bottoms floated safely in shallow rivers where deeper-hulled vessels could not travel.','平底船把谷物顺流运下，因为它们宽阔的船底能在较浅的河道安全漂行，吃水更深的船则无法通过。','Flatboats carried grain downstream / because their broad bottoms floated safely in shallow rivers / where deeper-hulled vessels could not travel.','flatboat 指船底平、常用于河道运输的船。','平底适合浅水河流运输，符合定义。')],mistakes:[M('The cargo ship drew fifteen metres of water and could not enter a shallow river, so the captain called it a flatboat.','The shallow-draft, flat-bottomed cargo vessel was a flatboat.','深吃水船不符合平底船适用于浅河的特点。')],quiz:[Q('flatboat',1,1,'A flatboat is designed with a?','broad flat bottom','deep pointed keel for ocean storms only','round balloon hull','broad flat bottom','平底船的特征是宽而平的船底。'),Q('flatboat',2,1,'Where might a flatboat carry cargo?','along a shallow river','through outer space','up a steep mountain trail','along a shallow river','平底船适合浅水河道。'),Q('flatboat',3,1,'Why use a flatboat in a shallow channel?','it needs less depth beneath the hull','it can fly over water','it has no hull','it needs less depth beneath the hull','平底结构适用于吃水较浅的河道。'),Q('flatboat',4,1,'The compound flatboat combines?','flat + boat','flap + boot','flame + board','flat + boat','该词由 flat 和 boat 组成。')]});
D('flatfish',{etymology:E('Flatfish combines flat and fish, describing flattened bottom-dwelling fish whose eyes are on the upper side of the body.','flatfish'),contexts:[C('flatfish.s1','海底伪装','The sole buried itself in the sand with both eyes facing upward, a typical flatfish posture that helped it watch for prey.','鳎鱼把自己埋进沙里，两只眼睛都朝上，这是典型比目鱼姿势，便于观察猎物。','The sole buried itself in the sand / with both eyes facing upward / a typical flatfish posture / that helped it watch for prey.','flatfish 是身体扁平、贴海底生活的一类鱼。','鳎鱼双眼在朝上的一侧并伏于海底，符合定义。')],mistakes:[M('The zoologist called a round-bodied fish with one eye on each side a flatfish that lies flat on the seabed.','The zoologist called the flattened seabed fish with both eyes on its upper side a flatfish.','身体圆、两侧各有一眼不符合比目鱼特征。')],quiz:[Q('flatfish',1,1,'A flatfish usually lies?','on the sea floor','in a treetop','inside a bird nest','on the sea floor','比目鱼通常贴海底生活。'),Q('flatfish',2,1,'A defining feature of many flatfish is?','both eyes on the upper side','feathers along the back','a shell covering the body','both eyes on the upper side','两只眼位于身体朝上的一侧。'),Q('flatfish',3,1,'Sole is an example of a?','flatfish','firefly','finch','flatfish','鳎鱼属于比目鱼类。'),Q('flatfish',4,1,'The name flatfish refers mainly to its?','flattened body shape','ability to fly','colour of its eggs','flattened body shape','flatfish 因身体扁平而得名。')]});
// FINAL CHECKPOINT
D('flattering',{etymology:E('Flattering is the -ing adjective from flatter. It can mean making someone look especially attractive or praising someone, sometimes without sincerity.','flattering'),contexts:[C('flattering.s1','服装建议','The tailor said the dark jacket was flattering because its cut emphasized the client’s shoulders without restricting movement.','裁缝说这件深色夹克很衬人，因为剪裁突出了顾客的肩部，又不妨碍活动。','The tailor said the dark jacket was flattering / because its cut emphasized the client’s shoulders / without restricting movement.','flattering 在此表示使人显得更好看；主语是衣服。','剪裁使穿着者外形更显精神，符合外观义。')],mistakes:[M('The tailor called the jacket flattering because it made the client look awkward and much less confident.','The tailor called the jacket unflattering because it made the client look awkward and less confident.','使人显得难看与 flattering 的外观义相反。')],quiz:[Q('flattering',1,1,'A flattering colour is one that?','makes the wearer look attractive','makes every person look ill','has no visible colour','makes the wearer look attractive','flattering 可指衣服或颜色衬人。'),Q('flattering',2,1,'Flattering praise can sometimes be?','insincere or exaggerated','a measurement of height','a type of fabric','insincere or exaggerated','夸奖义有时暗含奉承、不够真诚。'),Q('flattering',3,1,'Which collocation describes clothing?','a flattering dress','a flattering rainfall','a dress flattering of','a flattering dress','flattering 常修饰衣服，表示穿着效果好。'),Q('flattering',4,1,'A flattering portrait makes its subject look?','especially good','unrecognizable by accident','physically absent','especially good','肖像的 flattering 效果是突出优点。')]});
D('flattish',{etymology:E('Flattish combines flat with -ish, which can mean “somewhat” or “rather.” It describes a surface that is fairly flat but not perfectly level.','flattish'),contexts:[C('flattish.s1','地形描述','The trail crossed a flattish ridge where cyclists could rest, although the ground still rose slightly toward the eastern lookout.','小路穿过一段比较平缓的山脊，骑行者可以稍作休息，不过地面仍向东侧观景点微微升高。','The trail crossed a flattish ridge / where cyclists could rest / although the ground still rose slightly / toward the eastern lookout.','-ish 在此表示“有点、比较”，减弱 flat 的绝对程度。','山脊大体较平但仍有轻微坡度，符合 s1。')],mistakes:[M('The survey called the perfectly level table flattish because one edge stood a metre higher than the other.','The survey called the slightly uneven tabletop flattish because it was nearly level.','一边高出一米显然不接近平坦。')],quiz:[Q('flattish',1,1,'A flattish road is?','fairly flat but not perfectly level','extremely steep','completely vertical','fairly flat but not perfectly level','flattish 指比较平坦，并非绝对水平。'),Q('flattish',2,1,'The ending -ish in flattish suggests?','somewhat flat','made of metal','belonging to a fish','somewhat flat','-ish 表示“有点、比较”。'),Q('flattish',3,1,'Which surface is flattish?','a nearly level field with a gentle rise','a sheer cliff face','a round ball','a nearly level field with a gentle rise','微微起伏但整体近乎平坦。'),Q('flattish',4,1,'A flattish hilltop would be?','broad and nearly level','a sharp vertical peak only','deep underwater','broad and nearly level','flattish hilltop 表示较平缓的山顶。')]});
D('flaunt',{etymology:E('Flaunt is recorded in English in the sixteenth century; its origin is uncertain. As a verb it means to display something proudly to attract admiration; as a noun it can name such a display.','flaunt'),contexts:[C('flaunt.s1','消费行为','Rather than flaunt his new car, Mateo parked it at home and joined the neighbourhood fundraiser on foot.','马特奥没有炫耀新车，而是把车停在家里，步行参加社区募捐活动。','Rather than flaunt his new car / Mateo parked it at home / and joined the neighbourhood fundraiser on foot.','flaunt 作及物动词，后接被炫耀的物品。','把新车展示出来博人羡慕是 flaunt 的典型含义。')],mistakes:[M('The billionaire flaunted his wealth by hiding every luxury purchase and refusing to discuss it.','The billionaire flaunted his wealth by displaying his luxury purchases for everyone to admire.','隐藏财富而不展示与 flaunt 的炫耀义相反。')],quiz:[Q('flaunt',1,1,'To flaunt a new watch is to?','show it off proudly','hide it in a drawer','repair its battery','show it off proudly','flaunt 指得意地展示以吸引注意。'),Q('flaunt',2,1,'Which behaviour flaunts success?','posting a trophy prominently to invite admiration','putting the trophy away unseen','giving no sign that a prize was won','posting a trophy prominently to invite admiration','主动展示奖杯让人羡慕，符合动词义。'),Q('flaunt',3,2,'In “a flaunt of power,” flaunt is?','a noun naming a showy display','a verb meaning to whisper','an adjective for quiet agreement','a noun naming a showy display','s2 是炫耀性的展示行为名词。'),Q('flaunt',4,1,'Choose the standard pattern.','flaunt one’s achievements','flaunt at one’s achievements of','flaunt to achievements oneself','flaunt one’s achievements','flaunt 为及物动词，直接接炫耀的对象。')]});
D('flavin',{etymology:E('Flavin is formed from Latin flavus “yellow” and the chemical suffix -in. It names a yellow nitrogen-containing pigment related to riboflavin and involved in enzyme reactions.','flavin'),contexts:[C('flavin.s1','生化实验','The enzyme assay tracked a flavin compound as it accepted electrons, changing colour during the reaction.','酶分析追踪一种黄素化合物接受电子的过程；它在反应中发生了颜色变化。','The enzyme assay tracked a flavin compound / as it accepted electrons / changing colour during the reaction.','flavin 是化学名词，指黄色含氮色素类化合物。','黄素参与酶的电子转移反应，符合生化义。')],mistakes:[M('The chemist classified the colourless iron rod as flavin, a yellow nitrogen-containing pigment involved in enzyme chemistry.','The chemist classified the yellow nitrogen-containing compound as a flavin pigment.','铁棒不是黄素色素；其类别和性质均不符。')],quiz:[Q('flavin',1,1,'Flavins are a group of?','yellow nitrogen-containing pigments','colourless metal rods','sugars made only of water','yellow nitrogen-containing pigments','flavin 指黄色含氮色素。'),Q('flavin',2,1,'Flavin compounds can help enzymes?','transfer electrons','form wooden branches','measure sound volume','transfer electrons','黄素化合物参与酶的电子转移。'),Q('flavin',3,1,'The element flav- in flavin relates to?','yellow colour','water pressure','a bird call','yellow colour','其词根 flavus 意为黄色。'),Q('flavin',4,1,'Riboflavin is related to the class called?','flavins','flagpoles','flatboats','flavins','riboflavin 与黄素类相关。')]});
D('flavoring',{etymology:E('Flavoring is formed from flavor plus -ing. It names an ingredient added mainly to provide a particular taste or aroma rather than bulk.','flavoring'),contexts:[C('flavoring.s1','食品配方','Vanilla is the main flavoring in the custard, while the eggs and milk provide most of its volume and texture.','香草是蛋奶冻的主要调味成分，而鸡蛋和牛奶构成了大部分体积和质地。','Vanilla is the main flavoring in the custard / while the eggs and milk provide most of its volume and texture.','flavoring 指添加以提供味道或香气的成分。','香草用于调味而不是构成主体，符合定义。')],mistakes:[M('The recipe called plain water its flavoring even though it added no taste or aroma to the dish.','The recipe called vanilla its flavoring because it added a distinct aroma to the dish.','无味的水不承担调味作用。')],quiz:[Q('flavoring',1,1,'A flavoring is added mainly to?','give food a particular taste or aroma','supply the entire plate’s weight','cool a room','give food a particular taste or aroma','flavoring 用来增加风味。'),Q('flavoring',2,1,'Vanilla in ice cream is a?','flavoring','flagpole','filter','flavoring','香草为冰淇淋提供味道和香气。'),Q('flavoring',3,1,'Which is most likely a flavoring?','a small amount of lemon extract','the empty serving bowl','a cooking thermometer','a small amount of lemon extract','柠檬提取物添加后提供风味。'),Q('flavoring',4,1,'Flavoring differs from bulk ingredients because it mainly adds?','taste rather than volume','weight without taste','a paper label','taste rather than volume','其主要功能是提供风味而非增加主体分量。')]});
D('flawed',{etymology:E('Flawed is formed from flaw plus -ed. Flaw is an old word for a defect or weakness; flawed describes something imperfect, damaged, or based on faulty reasoning.','flawed'),contexts:[C('flawed.s1','项目评估','The plan was flawed because its cost estimate omitted transport and maintenance, so the committee asked for a revised budget.','该计划有缺陷，因为成本估算漏掉了运输和维护费用，因此委员会要求修订预算。','The plan was flawed / because its cost estimate omitted transport and maintenance / so the committee asked for a revised budget.','flawed 作表语形容词，说明计划有缺陷。','预算漏项使计划估算不完整，体现缺陷义。')],mistakes:[M('The flawless calculation was called flawed even though every input had been checked and the total was correct.','The calculation was flawed because one input had been entered incorrectly and changed the total.','完全核验无误的计算与有缺陷的判断相反。')],quiz:[Q('flawed',1,1,'A flawed plan is?','imperfect or based on a mistake','certain to work perfectly','made of polished stone','imperfect or based on a mistake','flawed 表示有缺陷或存在错误。'),Q('flawed',2,1,'An argument is flawed if it?','fails because of faulty reasoning','uses evidence correctly throughout','has a clear valid conclusion','fails because of faulty reasoning','推理错误会使论证有缺陷。'),Q('flawed',3,1,'Choose the natural collocation.','a flawed assumption','a flawed sunshine','a flawedly assumption','a flawed assumption','flawed 可修饰 assumption，表示错误假设。'),Q('flawed',4,1,'A flawed diamond may have?','a visible defect','no imperfections at all','a working engine','a visible defect','宝石有瑕疵属于字面缺陷义。')]});
D('flay',{etymology:E('Flay comes from Old English flēan “to skin,” from Germanic roots. Figuratively it can mean to attack or criticize someone or a work with extreme harshness.','flay'),contexts:[C('flay.s2','影评批评','The critic flayed the film for its careless history and flat characters, arguing that its large budget could not excuse the weak script.','评论家严厉抨击这部电影的史实错误和人物扁平，认为高预算不能成为剧本薄弱的借口。','The critic flayed the film / for its careless history and flat characters / arguing that its large budget could not excuse the weak script.','flay 作及物动词的比喻义，后接被严厉批评的人或作品。','评论家猛烈批评电影，符合 s2。')],mistakes:[M('The reviewer flayed the weak script by praising every scene and declaring the film beyond criticism.','The reviewer praised the script and declared the film beyond criticism.','赞扬并称无可批评与严厉抨击相反。')],quiz:[Q('flay',1,1,'To flay an animal is to?','remove its skin','feed it gently','measure its height','remove its skin','s1 是剥去动物皮肤。'),Q('flay',2,2,'A critic who flays a play?','attacks it with very harsh criticism','praises every part','helps actors sew costumes','attacks it with very harsh criticism','s2 比喻指猛烈批评。'),Q('flay',3,1,'Which is the literal sense of flay?','The butcher removed the hide from the carcass.','The critic mocked the play.','The audience applauded the cast.','The butcher removed the hide from the carcass.','剥去兽皮是字面义。'),Q('flay',4,2,'Which sentence uses flay figuratively?','The editorial flayed the minister over the delay.','The hunter flayed the animal carefully.','The cook fried the fish.','The editorial flayed the minister over the delay.','社论严厉批评部长是比喻义。')]});
D('flea',{etymology:E('Flea is an Old English word, recorded as flēah, with Germanic cognates. It names a tiny blood-feeding insect that jumps and lives on mammals or birds.','flea'),contexts:[C('flea.s1','宠物护理','The puppy scratched through the night, and the veterinarian found fleas beneath its collar before recommending treatment for both the animal and its bedding.','小狗整夜抓挠，兽医在它的项圈下发现了跳蚤，并建议同时处理宠物和寝具。','The puppy scratched through the night / and the veterinarian found fleas beneath its collar / before recommending treatment / for both the animal and its bedding.','flea 是寄生于动物、能跳跃的吸血昆虫。','兽医在宠物身上发现寄生虫并建议处理，符合义项。')],mistakes:[M('The veterinarian called the large, winged bird on the puppy’s collar a flea.','The veterinarian called the tiny jumping parasite beneath the puppy’s collar a flea.','大型有翅鸟不是跳蚤。')],quiz:[Q('flea',1,1,'A flea is a tiny insect that?','feeds on blood and can jump','makes honey in a hive','lives as a large fish','feeds on blood and can jump','跳蚤吸血且善于跳跃。'),Q('flea',2,1,'A dog scratching because of fleas may need?','treatment for the animal and bedding','a flight licence','a new flagpole','treatment for the animal and bedding','处理寄生虫要同时照顾宠物环境。'),Q('flea',3,1,'Which phrase is natural?','a flea infestation','a flea of timber','flea the river','a flea infestation','跳蚤大量寄生可称 flea infestation。'),Q('flea',4,1,'Fleas commonly live on?','mammals or birds','rocks in deep space','metal tools','mammals or birds','跳蚤寄生在哺乳动物或鸟类身上。')]});
D('fleck',{etymology:E('Fleck came into English from Germanic forms meaning a spot or speck. As a noun it is a tiny mark; as a verb it means to cover or mark something with small spots.','fleck'),contexts:[C('fleck.s2','林地光影','Sunlight flecked the forest floor through gaps in the leaves, making small bright patches shift as the branches moved.','阳光从叶片缝隙间洒下，在林地上点缀出斑驳亮点，并随着树枝摆动而移动。','Sunlight flecked the forest floor through gaps in the leaves / making small bright patches shift / as the branches moved.','fleck 在此作及物动词，表示使表面布满小斑点。','光线形成细小亮斑，体现动词义 s2。')],mistakes:[M('The sunlight flecked the wall by covering it with one completely uniform dark colour.','The sunlight flecked the wall with scattered bright spots.','均匀单色不构成零散的斑点。')],quiz:[Q('fleck',1,1,'A fleck of dust is?','a tiny speck','a large suitcase','a river valley','a tiny speck','s1 指细小斑点或碎屑。'),Q('fleck',2,2,'Sunlight flecked the wall means it?','marked it with small patches of light','painted it one uniform dark colour','made the wall disappear','marked it with small patches of light','s2 作动词表示点缀出小斑点。'),Q('fleck',3,1,'Which sentence uses fleck as a noun?','A fleck of paint remained on the glass.','The rain flecked the window.','She flecked the cloth with blue.','A fleck of paint remained on the glass.','a fleck 是名词，指一小点油漆。'),Q('fleck',4,2,'Choose the verbal use.','The spray flecked the mirror with droplets.','A fleck rested on the mirror.','The mirror had one fleck.','The spray flecked the mirror with droplets.','flecked 作动词使镜面出现小斑点。')]});
D('fledgling',{etymology:E('Fledgling is built from fledge “to grow feathers or become ready to fly” and -ling, a suffix for a young or developing being. It names a young bird or an inexperienced newcomer.','fledgling'),contexts:[C('fledgling.s2','创业团队','The fledgling company won its first regional contract but still needed experienced staff to manage rapid growth.','这家初创公司拿下了首份地区合同，但仍需要有经验的员工来管理快速增长。','The fledgling company won its first regional contract / but still needed experienced staff / to manage rapid growth.','fledgling 作定语表示新成立、经验尚浅。','刚获得首份合同且仍需经验支持，符合新创组织义 s2。')],mistakes:[M('The fledgling company had operated for a century and had already dominated every global market.','The established company had operated for a century and dominated its market.','经营百年的成熟企业并非刚起步的 fledgling company。')],quiz:[Q('fledgling',1,1,'A fledgling bird is?','a young bird learning to fly','a full-grown eagle with decades of experience','a fish living in deep water','a young bird learning to fly','s1 指刚长羽、正在学飞的幼鸟。'),Q('fledgling',2,2,'A fledgling business is?','new and still inexperienced','centuries old and fully established','a bird’s nest only','new and still inexperienced','s2 指刚起步、经验不足的人或公司。'),Q('fledgling',3,1,'A fledgling may fall from?','its nest','a courtroom chair','a boat engine','its nest','幼鸟在学习飞行时可能从巢中掉落。'),Q('fledgling',4,2,'Which firm is a fledgling?','a startup with its first customers','a centuries-old firm with a global monopoly','a firm that has never opened','a startup with its first customers','刚开始经营的初创企业符合比喻义。')]});
D('flesh-eating',{etymology:E('Flesh-eating is a transparent compound of flesh and eating. It describes an animal that feeds on the flesh of other animals rather than plants.','flesh-eating'),contexts:[C('flesh-eating.s1','恐龙纪录片','The documentary showed flesh-eating dinosaurs hunting in groups, while plant-eating species browsed among the ferns.','纪录片展示了食肉恐龙成群狩猎，而食草种类则在蕨类植物间取食。','The documentary showed flesh-eating dinosaurs hunting in groups / while plant-eating species browsed among the ferns.','flesh-eating 作复合形容词，修饰 dinosaurs。','捕食动物肉而非植物，符合食肉义。')],mistakes:[M('The film called a deer flesh-eating although it fed only on leaves and grass.','The film called the deer plant-eating because it fed on leaves and grass.','只吃植物的鹿不属于食肉动物。')],quiz:[Q('flesh-eating',1,1,'A flesh-eating animal gets food by?','eating the flesh of other animals','eating only leaves','absorbing sunlight','eating the flesh of other animals','flesh-eating 指以动物肉为食。'),Q('flesh-eating',2,1,'Which creature is most likely flesh-eating?','a predator that hunts other animals','a cow grazing on grass','a tree taking in sunlight','a predator that hunts other animals','捕食动物的掠食者符合定义。'),Q('flesh-eating',3,1,'Choose the correct hyphenated modifier.','flesh-eating bacteria','flesh eatingly bacteria','eating-flesh of bacteria','flesh-eating bacteria','复合形容词写作 flesh-eating。'),Q('flesh-eating',4,1,'Flesh-eating contrasts with?','plant-eating','fireproof','flickering','plant-eating','食肉与食草相对。')]});
D('fleshy',{etymology:E('Fleshy is formed from flesh plus -y. It can describe a person or body part with abundant soft flesh, or a thick, soft, juicy plant part.','fleshy'),contexts:[C('fleshy.s2','植物适应','The cactus stores water in its fleshy stem, which stays thick through the dry season when thinner leaves would lose moisture.','仙人掌把水储存在肉质茎中；在干旱季节，茎仍保持肥厚，而较薄的叶片会失去水分。','The cactus stores water in its fleshy stem / which stays thick through the dry season / when thinner leaves would lose moisture.','fleshy 修饰 stem，表示厚实、多汁的植物组织。','茎肥厚且储水，符合植物义 s2。')],mistakes:[M('The botanist described the cactus stem as fleshy because it was dry, thin, and brittle.','The botanist described the cactus stem as fleshy because it was thick and water-storing.','干、薄、易碎不符合肉质组织的特征。')],quiz:[Q('fleshy',1,1,'A fleshy hand is?','full and soft with abundant flesh','made of metal','completely skeletal','full and soft with abundant flesh','s1 描述肉多而丰满柔软。'),Q('fleshy',2,2,'A fleshy cactus stem is?','thick, soft, and able to store water','thin and brittle like dry paper','a wooden root','thick, soft, and able to store water','s2 指植物厚实多汁的组织。'),Q('fleshy',3,1,'Which phrase describes a person’s appearance?','a fleshy face','a fleshy equation','a fleshy thunderstorm','a fleshy face','fleshy 可形容脸部丰满多肉。'),Q('fleshy',4,2,'Why might a succulent have fleshy leaves?','they store water','they conduct electricity as wires','they are made of bone','they store water','肉质叶有助于储存水分。')]});
D('flexibly',{etymology:E('Flexibly is formed from flexible plus -ly; flexible comes through French and Latin flexibilis, from flectere “to bend.” It means bendably or in an adaptable way.','flexibly'),contexts:[C('flexibly.s2','工作安排','The team worked flexibly across time zones, shifting meeting hours each week so colleagues with caregiving duties could participate.','团队跨时区灵活工作，每周调整会议时间，让承担照护责任的同事也能参加。','The team worked flexibly across time zones / shifting meeting hours each week / so colleagues with caregiving duties could participate.','flexibly 修饰 worked，表示可随条件调整地工作。','团队改变时间安排以适应不同需求，符合引申义 s2。')],mistakes:[M('The team worked flexibly by refusing every schedule change and requiring all colleagues to use one fixed hour.','The team worked rigidly by refusing schedule changes and requiring one fixed hour.','拒绝任何调整、只接受固定时间与灵活安排相反。')],quiz:[Q('flexibly',1,1,'A wire bends flexibly when it?','bends without breaking','snaps immediately','turns into glass','bends without breaking','s1 指柔韧可弯地。'),Q('flexibly',2,2,'A flexibly arranged work schedule?','changes to fit people’s needs','never changes under any condition','applies only to metal','changes to fit people’s needs','s2 表示灵活变通地适应新条件。'),Q('flexibly',3,1,'Which sentence uses the physical sense?','The soft rod flexibly curved around the frame.','The team flexibly moved its meeting.','They planned flexibly across time zones.','The soft rod flexibly curved around the frame.','杆弯曲而不断体现物理柔韧义。'),Q('flexibly',4,2,'Which response is flexible in the figurative sense?','rescheduling so all team members can attend','rejecting every possible adjustment','canceling a project without discussion','rescheduling so all team members can attend','调整时间适应成员需求属于灵活变通。')]});
D('flexitime',{etymology:E('Flexitime combines flexible and time. It names an employment system in which workers can vary their starting and finishing hours while completing the required total.','flexitime'),contexts:[C('flexitime.s1','办公制度','The laboratory offers flexitime: employees may start earlier or later, provided they complete their contracted hours and attend core meetings.','实验室实行弹性工时：员工可以早些或晚些上班，只要完成合同工时并参加核心会议。','The laboratory offers flexitime / employees may start earlier or later / provided they complete their contracted hours / and attend core meetings.','flexitime 是可数或不可数制度名词，指弹性上下班时间安排。','时刻可调整但总工时和核心会议要求不变，符合定义。')],mistakes:[M('Under flexitime, staff must all arrive at exactly the same minute and cannot vary their working hours.','Under flexitime, staff may vary their start and finish times while meeting the required total hours.','完全固定统一的上下班时间与 flexitime 相反。')],quiz:[Q('flexitime',1,1,'Flexitime lets employees?','vary working hours while completing the required total','skip all work hours','work only at night','vary working hours while completing the required total','弹性工时允许调整时刻，但仍须完成规定时长。'),Q('flexitime',2,1,'A flexitime policy may allow a parent to?','shift the start time for school drop-off','avoid every contracted hour','change the company’s name','shift the start time for school drop-off','弹性安排可适应个人日程。'),Q('flexitime',3,1,'What usually remains required under flexitime?','the agreed total hours','the same arrival minute for everyone','no attendance at core meetings ever','the agreed total hours','弹性工时不免除总工时义务。'),Q('flexitime',4,1,'Flexitime is an arrangement about?','when employees work','how fish swim','how a bulb flashes','when employees work','flexitime 指工作时段制度。')]});
D('flickering',{etymology:E('Flickering is formed from flicker plus -ing. Flicker is an old verb for an unsteady, repeatedly appearing and disappearing light or movement.','flickering'),contexts:[C('flickering.s1','烛光阅读','They read the map by the flickering candlelight, shielding the page whenever a draft made the flame waver.','他们借摇曳的烛光看地图，每当穿堂风吹得火焰晃动时就用手护住地图。','They read the map by the flickering candlelight / shielding the page / whenever a draft made the flame waver.','flickering 作定语修饰 candlelight，表示光线忽明忽暗。','火焰受风摇摆使光线闪烁，符合义项。')],mistakes:[M('The flickering lamp gave a perfectly steady beam that never changed brightness or position.','The steady lamp gave a beam that never changed brightness or position.','光线完全稳定与 flickering 的闪烁不定相反。')],quiz:[Q('flickering',1,1,'Flickering light keeps?','appearing and disappearing or wavering','remaining perfectly steady','making no light at all','appearing and disappearing or wavering','flickering 描述光线忽明忽暗。'),Q('flickering',2,1,'A flickering candle is likely affected by?','air currents','a silent book','a dry road','air currents','气流会让烛火摇曳闪烁。'),Q('flickering',3,1,'Choose the natural phrase.','flickering candlelight','flickering solid stone','candlelight flickerly','flickering candlelight','flickering 可作前置定语修饰光线。'),Q('flickering',4,1,'A flickering screen may be?','turning brightness on and off irregularly','showing one still image with no change','made only from cloth','turning brightness on and off irregularly','屏幕亮度不稳定闪变称 flickering。')]});
D('flier',{etymology:E('Flier is formed from fly plus the agent suffix -er and is also a spelling variant of flyer. It can mean a person or creature in flight, or a small printed advertising sheet.','flier'),contexts:[C('flier.s2','社区宣传','Volunteers handed out a flier for the repair café, listing the date, address, and tools visitors should bring.','志愿者分发了修理咖啡馆的宣传单，上面列出日期、地址以及访客应带的工具。','Volunteers handed out a flier for the repair café / listing the date, address, and tools / visitors should bring.','flier 在此指宣传活动的小张印刷品。','列有活动信息并被分发的纸张符合传单义 s2。')],mistakes:[M('The volunteers handed out a flier for the event, but the sheet contained no information and was not printed on paper.','The volunteers handed out an informative printed flier for the event.','传单是宣传信息的印刷页；无信息也非纸张不符合此义。')],quiz:[Q('flier',1,1,'A flier in the first sense may be?','a person or creature that flies','a printed poster only','a laboratory bottle','a person or creature that flies','s1 指飞行者，也可指飞行中的鸟虫。'),Q('flier',2,2,'A shop distributes a flier to?','advertise an event or product','carry a passenger through the air','filter a drink','advertise an event or product','s2 指宣传商品或活动的传单。'),Q('flier',3,2,'Which detail belongs on an event flier?','date and location','the bird’s wing span only','a pipe diameter','date and location','活动传单通常列日期地点等信息。'),Q('flier',4,1,'A skilled flier can?','operate or travel in an aircraft','print only legal forms','grow into a fish','operate or travel in an aircraft','flier 的一个义项是飞行员或飞行者。')]});
D('flighty',{etymology:E('Flighty is formed from flight plus -y. Its figurative sense describes someone irresponsible, changeable, or easily distracted, as if the person’s attention keeps flying elsewhere.','flighty'),contexts:[C('flighty.s1','投资评估','Investors rejected the flighty proposal because its leaders changed the target market every week and could not explain the latest budget.','投资者拒绝了这个轻率多变的提案，因为负责人每周更换目标市场，也无法解释最新预算。','Investors rejected the flighty proposal / because its leaders changed the target market every week / and could not explain the latest budget.','flighty 修饰 proposal，语境中指计划反复无常、缺乏稳健。','目标和预算不断变化，体现轻率而不负责任的特征。')],mistakes:[M('The board called the flighty plan stable and responsible because its goals never changed and its budget was clear.','The board called the flighty plan unreliable because its goals kept changing and its budget was unclear.','目标反复变化、预算不清与稳定可靠相反。')],quiz:[Q('flighty',1,1,'A flighty person is often?','irresponsible and quick to change their mind','careful and perfectly consistent','unable to move physically','irresponsible and quick to change their mind','flighty 指轻率、主意易变。'),Q('flighty',2,1,'A flighty investment plan might?','switch goals repeatedly without sound reasons','keep a stable strategy for years','publish audited accounts on schedule','switch goals repeatedly without sound reasons','反复无常的计划符合 flighty。'),Q('flighty',3,1,'Which is closest in tone to flighty?','fickle','reliable','methodical','fickle','fickle 指易变，与 flighty 接近。'),Q('flighty',4,1,'Why might a team describe a colleague as flighty?','the colleague often abandons one idea for another','the colleague carefully follows one plan','the colleague writes every date down','the colleague often abandons one idea for another','轻易更改主意体现 flighty。')]});
D('flimsy',{etymology:E('Flimsy is recorded in English by the eighteenth century, but its origin is uncertain. As an adjective it describes fragile material or a weak, unconvincing excuse; as a noun it can mean very thin tracing paper.','flimsy'),contexts:[C('flimsy.s2','迟到解释','The supervisor rejected the flimsy excuse that the bus had vanished, since the driver’s log showed that it had arrived on time.','主管不接受“公交车消失了”这种站不住脚的借口，因为司机记录显示公交准时到达。','The supervisor rejected the flimsy excuse / that the bus had vanished / since the driver’s log showed / that it had arrived on time.','flimsy 修饰 excuse，表示理由薄弱、难以令人信服。','客观记录反驳借口，体现站不住脚的比喻义 s2。')],mistakes:[M('The flimsy excuse was convincing because independent records confirmed that the bus had disappeared.','The flimsy excuse was unconvincing because independent records showed that the bus had arrived.','flimsy 表示薄弱、不可信；被独立证据证实的说法不符合此处。')],quiz:[Q('flimsy',1,1,'A flimsy plastic bag is?','thin and easily torn','thick steel armour','impossible to break','thin and easily torn','s1 指材料单薄、容易破损。'),Q('flimsy',2,2,'A flimsy excuse is?','weak and hard to believe','supported by decisive proof','a strong building material','weak and hard to believe','s2 指站不住脚的借口。'),Q('flimsy',3,3,'As a noun, flimsy can mean?','very thin tracing or copying paper','a stone tool','a thick wooden board','very thin tracing or copying paper','s3 指薄纸、描图纸。'),Q('flimsy',4,2,'Which statement would be called a flimsy excuse?','an unsupported claim contradicted by the attendance log','a reason confirmed by several records','a clear explanation supported by evidence','an unsupported claim contradicted by the attendance log','证据直接反驳且没有依据的理由十分薄弱。')]});
D('flint',{etymology:E('Flint is an Old English word for the very hard stone used to make tools and sparks. The name also applies to a small hard piece in a lighter that produces a spark.','flint'),contexts:[C('flint.s2','打火机维修','The lighter failed to spark because its flint had worn down, so the repairer replaced the small piece beneath the wheel.','打火机因打火石磨损而无法打出火花，于是维修人员更换了滚轮下方的小硬块。','The lighter failed to spark / because its flint had worn down / so the repairer replaced the small piece beneath the wheel.','flint 在此指打火机内撞击后产生火星的小硬块。','更换磨损零件后可重新打火，符合 s2。')],mistakes:[M('The repairer replaced the lighter’s flint with soft wax, which could not strike the wheel or make sparks.','The repairer replaced the lighter’s worn flint with a hard piece that could strike the wheel and make sparks.','软蜡无法与打火轮摩擦产生火星，不适合作为打火石。')],quiz:[Q('flint',1,1,'Natural flint is a hard stone that can?','make sparks when struck against steel','melt in cold water','grow leaves in spring','make sparks when struck against steel','s1 是与钢相击能产生火花的燧石。'),Q('flint',2,2,'A lighter’s flint is the small piece that?','creates sparks when struck by the wheel','holds the liquid fuel','covers the flame','creates sparks when struck by the wheel','s2 指打火机内产生火星的硬块。'),Q('flint',3,1,'Early people used flint to make?','hard tools','paper curtains','rubber fish','hard tools','燧石坚硬，古人用来制作工具。'),Q('flint',4,2,'Why replace a worn lighter flint?','the lighter may no longer spark','the fuel becomes water','the case turns into stone','the lighter may no longer spark','打火石磨损会影响打火。')]});

})();
